__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Yesterday": "Gestern", "unread": "ungelesen", "All caught up": "Alles gelesen", "New message": "Neue Nachricht", "You": "Sie", "Send a message or instruction to your team.": "Senden Sie Ihrem Team eine Nachricht oder Anweisung.", "Messages from your employer will show here.": "Nachrichten Ihres Arbeitgebers erscheinen hier.", "Reply to": "Antwort an", "Understood 👍": "Verstanden 👍", "Done ✅": "Erledigt ✅", "On it": "Bin dran", "I need help": "Ich brauche Hilfe", "Type your reply": "Antwort eingeben", "Waiting for replies": "Warten auf Antworten", "New reply from": "Neue Antwort von", "Reply from": "Antwort von"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Messages now work like a chat: employees can reply to their employer, the employer can answer each employee, and everyone gets a tidy inbox with unread counts and quick replies": "Nachrichten funktionieren jetzt wie ein Chat: Mitarbeiter können ihrem Arbeitgeber antworten, der Arbeitgeber kann jedem Mitarbeiter antworten, und alle haben einen übersichtlichen Posteingang mit Zählern und Schnellantworten"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Delete this conversation?": "Diese Unterhaltung löschen?", "It will be removed from your messages.": "Sie wird aus Ihren Nachrichten entfernt.", "You can also remove it for everyone.": "Sie können sie auch für alle entfernen.", "Delete for me": "Für mich löschen", "Delete for everyone": "Für alle löschen", "Conversation deleted": "Unterhaltung gelöscht", "Conversation deleted for everyone": "Unterhaltung für alle gelöscht"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"selected": "ausgewählt", "Pick items from stock": "Artikel aus dem Bestand wählen", "items added": "Artikel hinzugefügt", "more, search to narrow down": "weitere, Suche eingrenzen", "Add selected": "Ausgewählte hinzufügen", "Tick boxes and Select all or Deselect all now appear wherever you pick stock: the sell page, the point of sale, invoices and purchase orders": "Kontrollkästchen und Alle auswählen oder Alle abwählen erscheinen jetzt überall, wo Bestand gewählt wird: Verkaufsseite, Kasse, Rechnungen und Bestellungen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Delete selected?": "Ausgewählte löschen?", "They will be removed from your messages.": "Sie werden aus Ihren Nachrichten entfernt.", "You can also remove them for everyone.": "Sie können sie auch für alle entfernen.", "Deleted": "Gelöscht", "Deleted for everyone": "Für alle gelöscht", "Select messages to delete": "Nachrichten zum Löschen auswählen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Logo and templates": "Logo und Vorlagen", "Logo updated": "Logo aktualisiert", "Logo removed": "Logo entfernt", "With your logo uploaded, your logo sits at the top left of every invoice, receipt and report and the Pesa mark at the top right, both the same size. Without a logo, the small Pesa mark is used at the top left.": "Mit hochgeladenem Logo steht Ihr Logo oben links auf jeder Rechnung, Quittung und jedem Bericht und das Pesa-Zeichen oben rechts, beide gleich groß. Ohne Logo wird das kleine Pesa-Zeichen oben links verwendet.", "Your logo prints at the top left of documents and the Pesa mark at the top right, at the same size.": "Ihr Logo wird oben links auf Dokumenten gedruckt und das Pesa-Zeichen oben rechts, in gleicher Größe.", "Letterhead removed from Settings. With a company logo uploaded, your logo prints at the top left of invoices, receipts and reports and the Pesa mark at the top right, both the same size": "Briefkopf aus den Einstellungen entfernt. Mit hochgeladenem Firmenlogo wird Ihr Logo oben links auf Rechnungen, Quittungen und Berichten gedruckt und das Pesa-Zeichen oben rechts, beide gleich groß"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Coming soon to": "Bald verfügbar auf"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Applies to everyone who has set it up on their device. Anyone else uses their password or PIN as before.": "Gilt für alle, die es auf ihrem Gerät eingerichtet haben. Alle anderen verwenden wie bisher ihr Passwort oder ihre PIN.", "Ask for fingerprint or face before deleting or restoring records": "Vor dem Löschen oder Wiederherstellen von Datensätzen nach Fingerabdruck oder Gesicht fragen", "Ask for it when Pesa opens or after 5 minutes away": "Beim Öffnen von Pesa oder nach 5 Minuten Abwesenheit danach fragen", "Cancelled or not recognised. Try again, or use your password or PIN.": "Abgebrochen oder nicht erkannt. Versuchen Sie es erneut oder verwenden Sie Ihr Passwort oder Ihre PIN.", "Confirm": "Bestätigen", "Confirm with your password or PIN": "Mit Passwort oder PIN bestätigen", "Could not use fingerprint or face just now. Use your password or PIN.": "Fingerabdruck oder Gesicht konnte gerade nicht verwendet werden. Verwenden Sie Ihr Passwort oder Ihre PIN.", "Fingerprint or face": "Fingerabdruck oder Gesicht", "Fingerprint or face is already set up on this device.": "Fingerabdruck oder Gesicht ist auf diesem Gerät bereits eingerichtet.", "Fingerprint or face is set up": "Fingerabdruck oder Gesicht ist eingerichtet", "Fingerprint or face is set up on this device.": "Fingerabdruck oder Gesicht ist auf diesem Gerät eingerichtet.", "Fingerprint or face unlock does not work from this web address. Open Pesa from its own website or the installed app.": "Die Entsperrung per Fingerabdruck oder Gesicht funktioniert von dieser Webadresse aus nicht. Öffnen Sie Pesa über die eigene Website oder die installierte App.", "Fingerprint or face unlock is not available here. It needs Windows Hello, Touch ID, Face ID or a fingerprint reader on this computer or device, and Pesa opened from its own website or the installed app.": "Die Entsperrung per Fingerabdruck oder Gesicht ist hier nicht verfügbar. Sie benötigt Windows Hello, Touch ID, Face ID oder einen Fingerabdruckleser auf diesem Computer oder Gerät, und Pesa muss über die eigene Website oder die installierte App geöffnet sein.", "Not verified": "Nicht verifiziert", "Pesa is locked": "Pesa ist gesperrt", "Remove from this device": "Von diesem Gerät entfernen", "Removed from this device": "Von diesem Gerät entfernt", "Set up fingerprint or face on this device": "Fingerabdruck oder Gesicht auf diesem Gerät einrichten", "Test it": "Testen", "Unlock with fingerprint or face": "Mit Fingerabdruck oder Gesicht entsperren", "Use password or PIN instead": "Stattdessen Passwort oder PIN verwenden", "Use the fingerprint or face unlock of this computer or device to sign in and to approve important actions. Pesa never sees or stores your fingerprint or face.": "Nutzen Sie die Entsperrung per Fingerabdruck oder Gesicht dieses Computers oder Geräts, um sich anzumelden und wichtige Aktionen zu bestätigen. Pesa sieht oder speichert Ihren Fingerabdruck oder Ihr Gesicht nie.", "Verified. It works.": "Verifiziert. Es funktioniert.", "Use fingerprint or face": "Fingerabdruck oder Gesicht verwenden", "or use your PIN": "oder verwenden Sie Ihre PIN", "or use your password": "oder verwenden Sie Ihr Passwort", "Fingerprint or face unlock": "Entsperrung per Fingerabdruck oder Gesicht", "Sign in quickly and approve important actions with the unlock your computer or device already has.": "Melden Sie sich schnell an und bestätigen Sie wichtige Aktionen mit der Entsperrung, die Ihr Computer oder Gerät bereits hat.", "Settings → Account → Fingerprint or face": "Einstellungen → Konto → Fingerabdruck oder Gesicht", "Open Settings and find Fingerprint or face under Account.": "Öffnen Sie die Einstellungen und suchen Sie unter Konto Fingerabdruck oder Gesicht.", "Tap Set up fingerprint or face on this device and follow the prompt from Windows Hello, Touch ID, Face ID or your Android fingerprint.": "Tippen Sie auf Fingerabdruck oder Gesicht auf diesem Gerät einrichten und folgen Sie der Aufforderung von Windows Hello, Touch ID, Face ID oder Ihrem Android-Fingerabdruck.", "On the sign in screen, tap your name and tap Use fingerprint or face. Your password or PIN still works.": "Tippen Sie auf dem Anmeldebildschirm auf Ihren Namen und dann auf Fingerabdruck oder Gesicht verwenden. Ihr Passwort oder Ihre PIN funktioniert weiterhin.", "Tick Ask for it when Pesa opens or after 5 minutes away to lock Pesa when nobody is using it.": "Aktivieren Sie Beim Öffnen von Pesa oder nach 5 Minuten Abwesenheit danach fragen, um Pesa zu sperren, wenn es niemand benutzt.", "Owners can tick Ask for fingerprint or face before deleting or restoring records, to protect important data.": "Inhaber können Vor dem Löschen oder Wiederherstellen von Datensätzen nach Fingerabdruck oder Gesicht fragen aktivieren, um wichtige Daten zu schützen.", "Set it up on each computer or device you use. If several people share one computer login, the computer cannot tell them apart, so use it on your own computer or device.": "Richten Sie es auf jedem Computer oder Gerät ein, das Sie verwenden. Wenn mehrere Personen ein Computerkonto teilen, kann der Computer sie nicht unterscheiden. Nutzen Sie es daher auf Ihrem eigenen Computer oder Gerät.", "Fingerprint and face unlock use the lock of your own computer or device, such as Windows Hello, Touch ID, Face ID or an Android fingerprint. Pesa never sees, stores or sends your fingerprint or face. The device only tells Pesa yes or no": "Die Entsperrung per Fingerabdruck und Gesicht nutzt die Sperre Ihres eigenen Computers oder Geräts, etwa Windows Hello, Touch ID, Face ID oder einen Android-Fingerabdruck. Pesa sieht, speichert oder sendet Ihren Fingerabdruck oder Ihr Gesicht nie. Das Gerät sagt Pesa nur Ja oder Nein", "Fingerprint or face unlock: set it up per computer or device in Settings, sign in with it, lock Pesa when you are away, and let owners require it before deleting or restoring records. Pesa never sees your fingerprint or face": "Entsperrung per Fingerabdruck oder Gesicht: richten Sie sie pro Computer oder Gerät in den Einstellungen ein, melden Sie sich damit an, sperren Sie Pesa bei Abwesenheit und lassen Sie Inhaber sie vor dem Löschen oder Wiederherstellen von Datensätzen verlangen. Pesa sieht nie Ihren Fingerabdruck oder Ihr Gesicht"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"That password is too easy to guess. Choose a different one.": "Dieses Passwort ist zu leicht zu erraten. Wählen Sie ein anderes.", "Choose a password of at least 8 characters.": "Wählen Sie ein Passwort mit mindestens 8 Zeichen.", "Signed out because Pesa was not used for a while.": "Abgemeldet, weil Pesa eine Weile nicht benutzt wurde.", "Security check": "Sicherheitsprüfung", "Secure connection": "Sichere Verbindung", "Pesa is open on a secure address (HTTPS). Information moving to your cloud project is encrypted on the way.": "Pesa ist über eine sichere Adresse (HTTPS) geöffnet. Informationen auf dem Weg zu Ihrem Cloud-Projekt werden verschlüsselt.", "This address is not secure. Open Pesa from its https website or the installed app.": "Diese Adresse ist nicht sicher. Öffnen Sie Pesa über die https-Website oder die installierte App.", "Guessing is limited": "Raten ist begrenzt", "After 3 wrong passwords or PINs, signing in locks for 1 minute, then 5, then 15. Every lock is written to the Activity log.": "Nach 3 falschen Passwörtern oder PINs ist die Anmeldung 1 Minute gesperrt, dann 5, dann 15. Jede Sperre wird im Aktivitätsprotokoll festgehalten.", "lock(s) in the last 30 days. Check the Activity log.": "Sperre in den letzten 30 Tagen. Prüfen Sie das Aktivitätsprotokoll.", "Strong passwords": "Starke Passwörter", "New passwords need at least 8 characters and cannot be a common password. Cashiers use a 4 digit PIN, so keep them on a device you trust.": "Neue Passwörter brauchen mindestens 8 Zeichen und dürfen kein häufiges Passwort sein. Kassierer verwenden eine 4-stellige PIN, nutzen Sie sie daher auf einem Gerät, dem Sie vertrauen.", "Automatic sign out": "Automatische Abmeldung", "Pesa signs people out after": "Pesa meldet Personen ab nach", "minutes without use.": "Minuten ohne Nutzung.", "Off. Turn it on so a computer left open does not stay signed in.": "Aus. Schalten Sie es ein, damit ein offen gelassener Computer nicht angemeldet bleibt.", "After": "Nach", "minutes": "Minuten", "Off": "Aus", "Set up on this device.": "Auf diesem Gerät eingerichtet.", "Not set up on this device. Add it under Settings → Account.": "Auf diesem Gerät nicht eingerichtet. Fügen Sie es unter Einstellungen → Konto hinzu.", "Approval before deleting": "Bestätigung vor dem Löschen", "On. Deleting or restoring records asks for fingerprint or face, or the password.": "Ein. Beim Löschen oder Wiederherstellen von Datensätzen wird nach Fingerabdruck oder Gesicht oder dem Passwort gefragt.", "Off. Turn it on under Settings → Account.": "Aus. Schalten Sie es unter Einstellungen → Konto ein.", "Cloud sync": "Cloud-Synchronisierung", "On. Use your own cloud project, keep its sync code private, and turn on its access rules (Row Level Security) so only your business can read the data.": "Ein. Nutzen Sie Ihr eigenes Cloud-Projekt, halten Sie den Sync-Code geheim und aktivieren Sie die Zugriffsregeln (Row Level Security), damit nur Ihr Geschäft die Daten lesen kann.", "Off. Your records stay on this device.": "Aus. Ihre Datensätze bleiben auf diesem Gerät.", "Backups": "Sicherungen", "A backup was made in the last week.": "In der letzten Woche wurde eine Sicherung erstellt.", "No recent backup. Make one from Settings so a lost or damaged device does not lose your records.": "Keine aktuelle Sicherung. Erstellen Sie eine in den Einstellungen, damit ein verlorenes oder beschädigtes Gerät nicht Ihre Datensätze kostet.", "About a firewall": "Über eine Firewall", "A firewall protects a server. Your Pesa website is only files, so for a firewall and protection against floods of traffic, put the website behind a free service such as Cloudflare. Ask the person who looks after your website to set it up.": "Eine Firewall schützt einen Server. Ihre Pesa-Website besteht nur aus Dateien. Für eine Firewall und Schutz vor Datenverkehrsfluten stellen Sie die Website hinter einen kostenlosen Dienst wie Cloudflare. Bitten Sie die Person, die Ihre Website betreut, es einzurichten.", "Open Activity log": "Aktivitätsprotokoll öffnen", "Pesa runs on your own computers and devices, so there is no server of ours to put a firewall on. These are the protections that apply to your business and what you can still do.": "Pesa läuft auf Ihren eigenen Computern und Geräten, daher gibt es keinen Server von uns für eine Firewall. Dies sind die Schutzmaßnahmen für Ihr Geschäft und was Sie noch tun können.", "Security: wrong password limits at sign in, stronger password rules (8 characters), automatic sign out, failed sign ins in the Activity log, a browser security policy, and a Security check for owners": "Sicherheit: Begrenzung falscher Passwörter bei der Anmeldung, strengere Passwortregeln (8 Zeichen), automatische Abmeldung, fehlgeschlagene Anmeldungen im Aktivitätsprotokoll, eine Browser-Sicherheitsrichtlinie und eine Sicherheitsprüfung für Inhaber", "See how your business is protected and switch on automatic sign out.": "Sehen Sie, wie Ihr Geschäft geschützt ist, und aktivieren Sie die automatische Abmeldung.", "Menu → Security check (Owner)": "Menü → Sicherheitsprüfung (Inhaber)", "Open the menu and tap Security check.": "Öffnen Sie das Menü und tippen Sie auf Sicherheitsprüfung.", "Read each line. A green tick means it is protected, an exclamation mark means there is something to do.": "Lesen Sie jede Zeile. Ein grüner Haken bedeutet geschützt, ein Ausrufezeichen bedeutet, dass etwas zu tun ist.", "Under Automatic sign out choose how long Pesa waits before it signs people out.": "Wählen Sie unter Automatische Abmeldung, wie lange Pesa wartet, bevor es Personen abmeldet.", "If sign in locks after wrong tries, look in the Activity log to see who was trying.": "Wenn die Anmeldung nach Fehlversuchen gesperrt wird, sehen Sie im Aktivitätsprotokoll nach, wer es versucht hat.", "Make a backup from Settings now and then.": "Erstellen Sie ab und zu eine Sicherung in den Einstellungen.", "Passwords need at least 8 characters. Cashiers use a 4 digit PIN, so only let them use Pesa on devices you trust.": "Passwörter brauchen mindestens 8 Zeichen. Kassierer verwenden eine 4-stellige PIN, lassen Sie sie Pesa daher nur auf Geräten nutzen, denen Sie vertrauen.", "After three wrong tries at signing in, the sign in locks for a while, and every lock is written to the Activity log so the owner can see it": "Nach drei falschen Anmeldeversuchen wird die Anmeldung für eine Weile gesperrt, und jede Sperre wird im Aktivitätsprotokoll festgehalten, damit der Inhaber sie sehen kann"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Browser and computer": "Browser und Computer", "cores": "Kerne", "Saving your records": "Speichern Ihrer Datensätze", "Records are saved safely in this browser.": "Datensätze werden sicher in diesem Browser gespeichert.", "Records are saved in a smaller space in this browser. Fine for a small shop.": "Datensätze werden in diesem Browser in einem kleineren Speicher gesichert. Für ein kleines Geschäft in Ordnung.", "This browser blocks saving. Turn off private browsing, or allow site data for Pesa.": "Dieser Browser blockiert das Speichern. Schalten Sie das private Surfen aus oder erlauben Sie Websitedaten für Pesa.", "Secure address": "Sichere Adresse", "Secure (https). Everything is available.": "Sicher (https). Alles ist verfügbar.", "Not a secure address. Pesa still works, using its built in security code, but installing the app, fingerprint and face unlock are not available.": "Keine sichere Adresse. Pesa funktioniert weiterhin mit seinem eingebauten Sicherheitscode, aber das Installieren der App sowie die Entsperrung per Fingerabdruck und Gesicht sind nicht verfügbar.", "Screen size": "Bildschirmgröße", "Full layout with the side menu.": "Volles Layout mit dem Seitenmenü.", "Compact layout. Open the menu with the button at the top left.": "Kompaktes Layout. Öffnen Sie das Menü mit der Schaltfläche oben links.", "Works without internet": "Funktioniert ohne Internet", "Installed as an app. It opens without internet.": "Als App installiert. Sie öffnet sich ohne Internet.", "This browser can keep Pesa for offline use. Use Install under Help.": "Dieser Browser kann Pesa für die Offline-Nutzung behalten. Verwenden Sie Installieren unter Hilfe.", "Offline use needs a secure address. Open Pesa from its https website.": "Die Offline-Nutzung benötigt eine sichere Adresse. Öffnen Sie Pesa über die https-Website.", "Invoices, receipts and reports (PDF)": "Rechnungen, Quittungen und Berichte (PDF)", "Ready.": "Bereit.", "Loads the first time you make a document. This needs internet once, then it is kept.": "Wird beim ersten Erstellen eines Dokuments geladen. Dafür wird einmal Internet benötigt, danach bleibt es erhalten.", "Barcode scanning with the camera": "Barcode-Scannen mit der Kamera", "Camera found, but this browser cannot read barcodes. A USB scanner works on every computer.": "Kamera gefunden, aber dieser Browser kann keine Barcodes lesen. Ein USB-Scanner funktioniert an jedem Computer.", "No camera access here. A USB barcode scanner works on every computer.": "Hier kein Kamerazugriff. Ein USB-Barcodescanner funktioniert an jedem Computer.", "Receipt printer and till drawer (Bluetooth)": "Quittungsdrucker und Kassenschublade (Bluetooth)", "Ready, in Chrome or Edge.": "Bereit, in Chrome oder Edge.", "Not in this browser. Use Chrome or Edge for the till drawer. Printing receipts to any printer still works.": "Nicht in diesem Browser. Verwenden Sie Chrome oder Edge für die Kassenschublade. Quittungen auf jedem Drucker zu drucken funktioniert weiterhin.", "Nearby Wi-Fi sync": "Synchronisierung über nahes WLAN", "Not in this browser. Use cloud sync instead.": "Nicht in diesem Browser. Verwenden Sie stattdessen die Cloud-Synchronisierung.", "Look and speed": "Aussehen und Geschwindigkeit", "Simpler look is on, for speed.": "Das einfachere Aussehen ist für mehr Tempo eingeschaltet.", "Full look. If Pesa feels slow, turn on the simpler look in Settings.": "Volles Aussehen. Wenn Pesa langsam wirkt, schalten Sie in den Einstellungen das einfachere Aussehen ein.", "Check this computer": "Diesen Computer prüfen", "Pesa works on Windows, Mac, Chromebook, Linux, Android and iPhone or iPad, using Chrome, Edge, Firefox or Safari from about 2020 onward. This shows what this computer can do. A tick means ready, an info mark means it works without that feature.": "Pesa läuft unter Windows, Mac, Chromebook, Linux, Android und iPhone oder iPad mit Chrome, Edge, Firefox oder Safari ab etwa 2020. Hier sehen Sie, was dieser Computer kann. Ein Haken bedeutet bereit, ein Info-Zeichen bedeutet, dass es ohne diese Funktion funktioniert.", "Copy this report": "Diesen Bericht kopieren", "Report copied": "Bericht kopiert", "Simpler look for older or slower computers": "Einfacheres Aussehen für ältere oder langsamere Computer", "Turns off blur and animations so Pesa runs faster on older computers.": "Schaltet Unschärfe und Animationen aus, damit Pesa auf älteren Computern schneller läuft.", "Works on all kinds of computers: a clear message instead of a blank page on browsers that are too old, sign in that works on plain http addresses, a simpler look for slow computers, and a Check this computer screen": "Läuft auf allen Arten von Computern: eine klare Meldung statt einer leeren Seite bei zu alten Browsern, Anmeldung, die auch auf einfachen http-Adressen funktioniert, ein einfacheres Aussehen für langsame Computer und eine Prüfung dieses Computers", "Check that Pesa suits this computer and make it faster.": "Prüfen Sie, ob Pesa zu diesem Computer passt, und machen Sie es schneller.", "Menu → Check this computer": "Menü → Diesen Computer prüfen", "Open the menu and tap Check this computer.": "Öffnen Sie das Menü und tippen Sie auf Diesen Computer prüfen.", "Read the list. A tick means that part is ready. An info mark means Pesa works without it.": "Lesen Sie die Liste. Ein Haken bedeutet, dass der Teil bereit ist. Ein Info-Zeichen bedeutet, dass Pesa ohne ihn funktioniert.", "If Pesa feels slow, open Settings and tick Simpler look for older or slower computers.": "Wenn Pesa langsam wirkt, öffnen Sie die Einstellungen und aktivieren Sie Einfacheres Aussehen für ältere oder langsamere Computer.", "If you see a message that the browser is too old, open Pesa in the latest Chrome, Edge or Firefox.": "Wenn Sie eine Meldung sehen, dass der Browser zu alt ist, öffnen Sie Pesa im neuesten Chrome, Edge oder Firefox.", "On Windows 7 or 8, use Chrome version 109.": "Verwenden Sie unter Windows 7 oder 8 Chrome Version 109.", "A USB barcode scanner and any printer work on every computer, even where the camera or Bluetooth do not.": "Ein USB-Barcodescanner und jeder Drucker funktionieren an jedem Computer, auch dort, wo Kamera oder Bluetooth nicht funktionieren."}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"My voice": "Meine Stimme", "Record each training slide in your own voice. Your recording plays instead of the computer or device voice. Any slide you have not recorded keeps the computer voice.": "Sprechen Sie jede Schulungsfolie mit Ihrer eigenen Stimme ein. Ihre Aufnahme wird anstelle der Computer- oder Gerätestimme abgespielt. Folien ohne Aufnahme behalten die Computerstimme.", "Recording language": "Aufnahmesprache", "of": "von", "slides recorded": "Folien aufgenommen", "Recorded": "Aufgenommen", "Welcome greeting": "Begrüßung", "Said when Pesa opens": "Wird beim Öffnen von Pesa gesprochen", "recorded": "aufgenommen", "Save my voice pack": "Mein Stimmpaket speichern", "Load a voice pack": "Stimmpaket laden", "Delete my recordings": "Meine Aufnahmen löschen", "Recordings are kept on this computer or device. To use them on other computers or devices, save a voice pack and load it there.": "Aufnahmen bleiben auf diesem Computer oder Gerät. Um sie auf anderen Computern oder Geräten zu nutzen, speichern Sie ein Stimmpaket und laden Sie es dort.", "Nothing recorded yet": "Noch nichts aufgenommen", "Voice pack saved": "Stimmpaket gespeichert", "Could not save the voice pack": "Stimmpaket konnte nicht gespeichert werden", "recordings loaded": "Aufnahmen geladen", "That is not a Pesa voice pack": "Das ist kein Pesa-Stimmpaket", "This deletes every voice recording on this computer or device. The computer voice will be used again.": "Dadurch wird jede Sprachaufnahme auf diesem Computer oder Gerät gelöscht. Die Computerstimme wird wieder verwendet.", "Delete": "Löschen", "Recordings deleted": "Aufnahmen gelöscht", "Text changed since you recorded": "Text seit der Aufnahme geändert", "Not recorded yet": "Noch nicht aufgenommen", "Tap a slide to record it. Read the words on the screen in your own way. You do not need to say them word for word.": "Tippen Sie auf eine Folie, um sie aufzunehmen. Lesen Sie die Worte auf dem Bildschirm auf Ihre eigene Art. Sie müssen sie nicht wörtlich sprechen.", "Delete this recording": "Diese Aufnahme löschen", "The computer voice will read this slide again.": "Die Computerstimme liest diese Folie wieder vor.", "Recording deleted": "Aufnahme gelöscht", "Read this out loud": "Laut vorlesen", "Start recording": "Aufnahme starten", "This browser cannot record. Record on your computer or device with its voice recorder app, then add the file here.": "Dieser Browser kann nicht aufnehmen. Nehmen Sie mit der Sprachrekorder-App Ihres Computers oder Geräts auf und fügen Sie die Datei hier hinzu.", "Add an audio file instead": "Stattdessen eine Audiodatei hinzufügen", "That file is too big. Keep each slide under 25 MB.": "Diese Datei ist zu groß. Halten Sie jede Folie unter 25 MB.", "Pesa could not read that audio file.": "Pesa konnte diese Audiodatei nicht lesen.", "Stop": "Stopp", "Listen": "Anhören", "Save and record next slide": "Speichern und nächste Folie aufnehmen", "Record again": "Erneut aufnehmen", "Saved": "Gespeichert", "Could not save the recording": "Aufnahme konnte nicht gespeichert werden", "Could not start recording.": "Aufnahme konnte nicht gestartet werden.", "That was too short. Try again.": "Das war zu kurz. Versuchen Sie es erneut.", "Pesa is not allowed to use the microphone. Allow the microphone for this site in the browser, then try again.": "Pesa darf das Mikrofon nicht verwenden. Erlauben Sie das Mikrofon für diese Seite im Browser und versuchen Sie es erneut.", "Could not start the microphone. Check that one is connected.": "Das Mikrofon konnte nicht gestartet werden. Prüfen Sie, ob eines angeschlossen ist.", "Record my voice": "Meine Stimme aufnehmen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Record hands free": "Freihändig aufnehmen", "Press Start, then read each slide out loud one after the other. When you stop talking for a moment, Pesa saves that slide and shows the next one. You do not need to touch the screen between slides.": "Drücken Sie Start und lesen Sie dann jede Folie nacheinander laut vor. Wenn Sie kurz aufhören zu sprechen, speichert Pesa diese Folie und zeigt die nächste. Sie müssen den Bildschirm zwischen den Folien nicht berühren.", "Pause that ends a slide": "Pause, die eine Folie beendet", "Short": "Kurz", "Normal": "Normal", "Long": "Lang", "seconds": "Sekunden", "Record again the slides I already have": "Bereits vorhandene Folien erneut aufnehmen", "Start": "Start", "Find a quiet place. Pause for about 3 seconds after each slide. Pauses inside a slide, like between sentences, are fine.": "Suchen Sie einen ruhigen Ort. Machen Sie nach jeder Folie etwa 3 Sekunden Pause. Pausen innerhalb einer Folie, etwa zwischen Sätzen, sind in Ordnung.", "slides to record": "Folien aufzunehmen", "about": "etwa", "minutes": "Minuten", "already recorded and skipped": "bereits aufgenommen und übersprungen", "Nothing to record": "Nichts aufzunehmen", "Slide": "Folie", "Redo last slide": "Letzte Folie wiederholen", "Skip this slide": "Diese Folie überspringen", "Stop recording": "Aufnahme beenden", "Read this slide again": "Diese Folie noch einmal lesen", "Stopped": "Gestoppt", "All done": "Alles erledigt", "slides saved in your voice.": "Folien in Ihrer Stimme gespeichert.", "Done": "Fertig", "Waiting for you to start reading": "Warte darauf, dass Sie zu lesen beginnen", "Listening": "Höre zu", "Getting ready": "Wird vorbereitet", "now the next slide": "jetzt die nächste Folie", "Read the slides one after another and Pesa saves each one by itself. Or tap a lesson below to record slide by slide.": "Lesen Sie die Folien nacheinander, und Pesa speichert jede selbst. Oder tippen Sie unten auf eine Lektion, um Folie für Folie aufzunehmen.", "Record this whole lesson hands free": "Diese ganze Lektion freihändig aufnehmen"}); });
