__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Activate key": "Schlüssel aktivieren", "Ask the owner to renew.": "Bitten Sie den Inhaber, zu verlängern.", "Copy reference": "Referenz kopieren", "Could not check the key on this device.": "Der Schlüssel konnte auf diesem Gerät nicht geprüft werden.", "Documents version": "Dokumentenversion", "Download a backup of my data": "Sicherung meiner Daten herunterladen", "Email support": "Support per E-Mail", "Email us instead": "Schreiben Sie uns stattdessen eine E-Mail", "Ended": "Abgelaufen", "Ended, short grace period": "Abgelaufen, kurze Nachfrist", "Free trial": "Kostenlose Testphase", "Free trial: {0} days left.": "Kostenlose Testphase: noch {0} Tage.", "I have a licence key": "Ich habe einen Lizenzschlüssel", "I have read and agree to the Pesa confidentiality and privacy agreement and the Terms of Service.": "Ich habe die Pesa-Vereinbarung zu Vertraulichkeit und Datenschutz sowie die Nutzungsbedingungen gelesen und stimme zu.", "Licence activated. Thank you!": "Lizenz aktiviert. Vielen Dank!", "Licence and subscription": "Lizenz und Abonnement", "Licence key": "Lizenzschlüssel", "Licence reference": "Lizenzreferenz", "Message support on WhatsApp": "Support per WhatsApp schreiben", "Only the owner can activate a key.": "Nur der Inhaber kann einen Schlüssel aktivieren.", "Open the menu and tap Licence and subscription.": "Öffnen Sie das Menü und tippen Sie auf Lizenz und Abonnement.", "Paste your licence key first.": "Fügen Sie zuerst Ihren Lizenzschlüssel ein.", "Plan": "Tarif", "Plans": "Tarife", "Please ask the owner of the business to renew the subscription.": "Bitte bitten Sie den Inhaber des Geschäfts, das Abonnement zu verlängern.", "Read the Terms of Service": "Nutzungsbedingungen lesen", "Reference copied": "Referenz kopiert", "Renew on WhatsApp": "Per WhatsApp verlängern", "Send this when you subscribe or renew.": "Senden Sie diese beim Abonnieren oder Verlängern.", "Subscribe on WhatsApp": "Per WhatsApp abonnieren", "Terms of Service": "Nutzungsbedingungen", "Terms, privacy and support": "Bedingungen, Datenschutz und Support", "That does not look like a Pesa licence key. Copy the whole key, starting with PESA1.": "Das sieht nicht wie ein Pesa-Lizenzschlüssel aus. Kopieren Sie den ganzen Schlüssel, der mit PESA1 beginnt.", "That key is damaged. Copy it again, completely.": "Dieser Schlüssel ist beschädigt. Kopieren Sie ihn erneut, vollständig.", "This device cannot check licence keys. Open Pesa from its web address (https) and try again.": "Dieses Gerät kann Lizenzschlüssel nicht prüfen. Öffnen Sie Pesa über seine Webadresse (https) und versuchen Sie es erneut.", "This key is not valid for this version of Pesa.": "Dieser Schlüssel gilt nicht für diese Version von Pesa.", "This key is not valid. Check that it was copied completely.": "Dieser Schlüssel ist ungültig. Prüfen Sie, ob er vollständig kopiert wurde.", "This key was issued for a different business. Send your Licence reference to get the right one.": "Dieser Schlüssel wurde für ein anderes Geschäft ausgestellt. Senden Sie Ihre Lizenzreferenz, um den richtigen zu erhalten.", "Trial ends": "Testphase endet", "Unlimited staff accounts": "Unbegrenzte Mitarbeiterkonten", "Up to {0} staff accounts": "Bis zu {0} Mitarbeiterkonten", "You already have a key that lasts longer than this one.": "Sie haben bereits einen Schlüssel, der länger gilt als dieser.", "Your free trial has ended": "Ihre kostenlose Testphase ist beendet", "Your records are safe and nothing has been deleted. Subscribe to carry on selling with Pesa.": "Ihre Daten sind sicher und nichts wurde gelöscht. Abonnieren Sie, um mit Pesa weiter zu verkaufen.", "Your subscription ended. Pesa locks in {0} days unless you renew.": "Ihr Abonnement ist abgelaufen. Pesa sperrt in {0} Tagen, wenn Sie nicht verlängern.", "Your subscription ends in {0} days.": "Ihr Abonnement endet in {0} Tagen.", "Your subscription has ended": "Ihr Abonnement ist abgelaufen", "Your {0} plan allows up to {1} {2}. Upgrade to add more.": "Ihr Tarif {0} erlaubt bis zu {1} {2}. Wechseln Sie auf einen größeren Tarif, um mehr hinzuzufügen.", "branches": "Filialen", "days left": "Tage übrig", "staff accounts": "Mitarbeiterkonten", "unlimited branches": "unbegrenzte Filialen", "up to {0} branches": "bis zu {0} Filialen", "The sync code must be at least 16 letters or digits. Tap Generate code.": "Der Sync-Code muss mindestens 16 Buchstaben oder Ziffern haben. Tippen Sie auf Code erzeugen."}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Download as": "Herunterladen als", "File format": "Dateiformat", "PDF document": "PDF-Dokument", "Word document": "Word-Dokument", "Excel spreadsheet": "Excel-Tabelle", "CSV (comma separated)": "CSV (kommagetrennt)", "Web page": "Webseite", "Rich text": "Rich Text", "Plain text": "Nur Text", "Picture (PNG)": "Bild (PNG)", "Picture (JPG)": "Bild (JPG)", "Looks the same everywhere. Best for sending and printing.": "Sieht überall gleich aus. Am besten zum Senden und Drucken.", "Opens in Microsoft Word, Google Docs and LibreOffice, so you can edit it.": "Öffnet in Microsoft Word, Google Docs und LibreOffice, sodass Sie es bearbeiten können.", "Opens in Excel and Google Sheets. Amounts are real numbers you can add up.": "Öffnet in Excel und Google Sheets. Beträge sind echte Zahlen, die Sie addieren können.", "Plain table data for Excel, accounting programs and imports.": "Einfache Tabellendaten für Excel, Buchhaltungsprogramme und Importe.", "Opens in any browser and can be printed from there.": "Öffnet in jedem Browser und kann von dort gedruckt werden.", "Opens in WordPad, TextEdit, Word and most editors.": "Öffnet in WordPad, TextEdit, Word und den meisten Editoren.", "Words and numbers only. Works anywhere.": "Nur Wörter und Zahlen. Funktioniert überall.", "A sharp picture of the document, handy for WhatsApp.": "Ein scharfes Bild des Dokuments, praktisch für WhatsApp.", "A smaller picture of the document.": "Ein kleineres Bild des Dokuments.", "Created with Pesa": "Erstellt mit Pesa", "Couldn’t make that format. Try PDF instead.": "Dieses Format konnte nicht erstellt werden. Versuchen Sie stattdessen PDF.", "Download full report": "Vollständigen Bericht herunterladen", "Download report": "Bericht herunterladen", "Download invoice": "Rechnung herunterladen", "Make labels": "Etiketten erstellen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Tax records (NamRA)": "Steuerbelege (NamRA)", "NamRA has not published its e-invoicing rules yet. Turn this on to keep a numbered, tamper-evident tax record of every sale on this device, ready for when it does. Nothing is sent to NamRA until you enter an address and key below. Selling never waits for tax or the internet.": "NamRA hat seine Regeln für E-Rechnungen noch nicht veröffentlicht. Schalten Sie dies ein, um für jeden Verkauf auf diesem Gerät einen nummerierten, manipulationssicheren Steuerbeleg zu führen, bereit für den Zeitpunkt, an dem sie gelten. Es wird nichts an NamRA gesendet, bis Sie unten eine Adresse und einen Schlüssel eingeben. Verkäufe warten nie auf Steuer oder Internet.", "Set a VAT rate above 0 first (Reports, VAT summary). Tax records need it.": "Legen Sie zuerst einen MwSt-Satz über 0 fest (Berichte, MwSt-Übersicht). Steuerbelege benötigen ihn.", "Keep tax records on this device": "Steuerbelege auf diesem Gerät führen", "Your business": "Ihr Unternehmen", "Tax number (TIN)": "Steuernummer (TIN)", "Branch code": "Filialcode", "This device": "Dieses Gerät", "Terminal ID": "Terminal-ID", "Locked: this device already has tax records. Use a different Terminal ID on every other device.": "Gesperrt: Dieses Gerät hat bereits Steuerbelege. Verwenden Sie auf jedem anderen Gerät eine andere Terminal-ID.", "Use a different Terminal ID on every computer or device. It cannot be changed after the first sale.": "Verwenden Sie auf jedem Computer oder Gerät eine andere Terminal-ID. Sie kann nach dem ersten Verkauf nicht mehr geändert werden.", "NamRA address (https)": "NamRA-Adresse (https)", "optional": "optional", "Access key": "Zugangsschlüssel", "The address and key stay on this device only.": "Adresse und Schlüssel bleiben nur auf diesem Gerät.", "Waiting to send": "Wartet auf Versand", "Cleared": "Freigegeben", "Needs attention": "Braucht Aufmerksamkeit", "Not recording yet. Fill in every field above, turn it on and save.": "Es wird noch nicht aufgezeichnet. Füllen Sie alle Felder oben aus, schalten Sie es ein und speichern Sie.", "Recording tax records on this device. Nothing is sent: no address and key yet.": "Steuerbelege werden auf diesem Gerät aufgezeichnet. Es wird nichts gesendet: noch keine Adresse und kein Schlüssel.", "Sending is stopped because the address or key was refused. Check them, then tap Resume.": "Der Versand ist gestoppt, weil Adresse oder Schlüssel abgelehnt wurden. Prüfen Sie beides und tippen Sie dann auf Fortsetzen.", "Offline. Records are safe and will send when you are back online.": "Offline. Die Belege sind sicher und werden gesendet, sobald Sie wieder online sind.", "Sending in the background.": "Versand im Hintergrund.", "Send now": "Jetzt senden", "Retry failed": "Fehlgeschlagene wiederholen", "Resume": "Fortsetzen", "Enter your tax number (TIN): letters, numbers and dashes, 4 to 20 characters.": "Geben Sie Ihre Steuernummer (TIN) ein: Buchstaben, Ziffern und Bindestriche, 4 bis 20 Zeichen.", "Enter a branch code: letters, numbers and dashes, up to 16 characters.": "Geben Sie einen Filialcode ein: Buchstaben, Ziffern und Bindestriche, bis zu 16 Zeichen.", "Enter a Terminal ID for this device: letters, numbers and dashes, up to 16 characters.": "Geben Sie eine Terminal-ID für dieses Gerät ein: Buchstaben, Ziffern und Bindestriche, bis zu 16 Zeichen.", "The address must start with https://": "Die Adresse muss mit https:// beginnen", "Sale saved. Its tax record needs attention: open Settings, Tax records.": "Verkauf gespeichert. Der Steuerbeleg braucht Aufmerksamkeit: Einstellungen, Steuerbelege öffnen.", "Keep a numbered, tamper-evident tax record of every sale, ready for NamRA e-invoicing when it starts.": "Führen Sie für jeden Verkauf einen nummerierten, manipulationssicheren Steuerbeleg, bereit für die NamRA-E-Rechnung, sobald sie beginnt.", "Set up tax records": "Steuerbelege einrichten", "Tax category": "Steuerkategorie", "Standard rate": "Normalsatz", "Zero rated (0%)": "Nullsatz (0%)", "Exempt": "Befreit"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Tap to skip": "Zum Überspringen tippen", "Show the opening animation when Pesa starts": "Startanimation beim Öffnen von Pesa zeigen", "Watch the opening animation": "Startanimation ansehen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Legal name on your BIPA certificate": "Rechtlicher Name auf Ihrem BIPA-Zertifikat", "The number has the usual BIPA shape.": "Die Nummer hat die übliche BIPA-Form.", "This does not look like the usual format (for example CC/2024/00123). You can still save it if it is correct.": "Das sieht nicht nach dem üblichen Format aus (zum Beispiel CC/2024/00123). Sie können es trotzdem speichern, wenn es stimmt.", "Verified with BIPA": "Von BIPA bestätigt", "Entered by you, not checked with BIPA": "Von Ihnen eingegeben, nicht mit BIPA geprüft", "Look it up on the BIPA website": "Auf der BIPA-Website nachschlagen", "Business registration: add your BIPA registration number and the legal name on your certificate when you register or in Company details. Pesa checks the number looks right and keeps an honest note that you entered it, but it cannot confirm it with BIPA": "Geschäftsregistrierung: Fügen Sie Ihre BIPA-Registrierungsnummer und den rechtlichen Namen auf Ihrem Zertifikat bei der Registrierung oder unter Firmendaten hinzu. Pesa prüft, ob die Nummer plausibel aussieht, und vermerkt ehrlich, dass Sie sie eingegeben haben, kann sie aber nicht mit BIPA bestätigen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Type a name instead": "Stattdessen Namen eingeben", "Import cost calculator": "Importkosten-Rechner", "Work out what imported stock really costs you once freight, clearing fees and customs duty are added. The extra costs are shared across the products by how much you spent on each.": "Berechnen Sie, was importierte Ware Sie wirklich kostet, wenn Fracht, Abfertigungsgebühren und Zoll hinzukommen. Die Zusatzkosten werden nach dem Einkaufswert auf die Produkte verteilt.", "Supplier currency": "Währung des Lieferanten", "South African rand (ZAR)": "Südafrikanischer Rand (ZAR)", "Namibian dollar (N$)": "Namibia-Dollar (N$)", "Another currency": "Andere Währung", "N$ for 1 unit of that currency": "N$ für 1 Einheit dieser Währung", "Freight": "Fracht", "Clearing fees": "Abfertigungsgebühren", "Customs duty": "Zoll", "Mark-up on cost (%)": "Aufschlag auf die Kosten (%)", "Products on the supplier invoice": "Produkte auf der Lieferantenrechnung", "Add another product": "Weiteres Produkt hinzufügen", "Supplier price each": "Lieferantenpreis pro Stück", "Add a quantity and the supplier price to see the true cost": "Geben Sie Menge und Lieferantenpreis ein, um die wahren Kosten zu sehen", "True cost of each product": "Wahre Kosten pro Produkt", "Supplier price": "Lieferantenpreis", "extra costs": "Zusatzkosten", "Suggested price": "Vorgeschlagener Preis", "Use as cost price": "Als Einkaufspreis übernehmen", "each": "pro Stück", "Whole order, landed": "Gesamte Bestellung, verzollt und geliefert", "Import VAT and any stock already on your shelf are not included. “Use as cost price” replaces the product’s cost price with the figure above.": "Einfuhr-MwSt und Ware, die schon im Regal liegt, sind nicht enthalten. „Als Einkaufspreis übernehmen“ ersetzt den Einkaufspreis des Produkts durch den Wert oben.", "Cost price updated": "Einkaufspreis aktualisiert", "Mobile money check": "Mobile-Money-Abgleich", "Pesa cannot read your text messages. Copy the payment messages from your messages app, paste them below, and Pesa lines them up with the wallet sales you recorded. Leave a blank line between messages.": "Pesa kann Ihre SMS nicht lesen. Kopieren Sie die Zahlungsnachrichten aus Ihrer Nachrichten-App, fügen Sie sie unten ein, und Pesa gleicht sie mit den erfassten Wallet-Verkäufen ab. Lassen Sie zwischen den Nachrichten eine Leerzeile.", "Day to check": "Zu prüfender Tag", "Pasted messages": "Eingefügte Nachrichten", "Paste the payment messages here": "Zahlungsnachrichten hier einfügen", "Check": "Prüfen", "No wallet sales on this day and no payment messages pasted": "Keine Wallet-Verkäufe an diesem Tag und keine Zahlungsnachrichten eingefügt", "wallet sales matched a message": "Wallet-Verkäufe passten zu einer Nachricht", "message(s) with no sale": "Nachricht(en) ohne Verkauf", "Wallet sales": "Wallet-Verkäufe", "No reference recorded": "Keine Referenz erfasst", "Matched by amount only, no reference.": "Nur nach Betrag zugeordnet, keine Referenz.", "Matched by reference.": "Nach Referenz zugeordnet.", "Message says": "Nachricht nennt", "difference": "Differenz", "Messages with no matching sale": "Nachrichten ohne passenden Verkauf", "pasted message(s) skipped: no amount, or not a payment you received.": "eingefügte Nachricht(en) übersprungen: kein Betrag oder keine empfangene Zahlung.", "Pesa reads the amount and reference from the wording of each message. Wording differs between providers, so always glance at anything marked as not matched.": "Pesa liest Betrag und Referenz aus dem Wortlaut jeder Nachricht. Der Wortlaut unterscheidet sich je nach Anbieter, prüfen Sie daher alles, was als nicht zugeordnet markiert ist.", "more": "weitere", "This is a check, not a block. Confirm tax rules with NamRA if you are unsure.": "Dies ist eine Prüfung, keine Sperre. Klären Sie Steuerregeln im Zweifel mit NamRA.", "has no selling price": "hat keinen Verkaufspreis", "is priced below its cost": "ist unter dem Einkaufspreis ausgezeichnet", "is marked tax exempt, but alcohol and tobacco are normally charged VAT at the standard rate": "ist als steuerbefreit markiert, aber Alkohol und Tabak unterliegen normalerweise dem MwSt-Normalsatz", "Matched": "Zugeordnet", "Amount differs": "Betrag weicht ab", "No message found": "Keine Nachricht gefunden", "True cost of imported stock after freight, clearing and duty": "Wahre Kosten importierter Ware nach Fracht, Abfertigung und Zoll", "Match wallet sales with payment messages you paste in": "Wallet-Verkäufe mit eingefügten Zahlungsnachrichten abgleichen", "Three new business tools: an import cost calculator that shares freight, clearing and duty across your products to show the true cost of each, a mobile money check that lines up payment messages you paste in with your wallet sales, and a quick check at the till for missing prices, selling below cost and wrong tax categories": "Drei neue Geschäftswerkzeuge: ein Importkosten-Rechner, der Fracht, Abfertigung und Zoll auf Ihre Produkte verteilt und die wahren Kosten zeigt, ein Mobile-Money-Abgleich, der eingefügte Zahlungsnachrichten mit Ihren Wallet-Verkäufen abgleicht, und eine schnelle Prüfung an der Kasse auf fehlende Preise, Verkauf unter Einkaufspreis und falsche Steuerkategorien"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Show more":"Mehr anzeigen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Pesa hit a snag. Your saved records are not affected. If something looks stuck, reload the page.": "Pesa ist auf ein Problem gestoßen. Ihre gespeicherten Daten sind nicht betroffen. Wenn etwas hängt, laden Sie die Seite neu.", "Faster searching and scanning: barcodes are found instantly however many products you have, the till product list loads in pages with a Show more button, and a calm message appears instead of a frozen screen if something unexpected goes wrong": "Schnelleres Suchen und Scannen: Barcodes werden sofort gefunden, egal wie viele Produkte Sie haben, die Produktliste an der Kasse lädt seitenweise mit einer Schaltfläche „Mehr anzeigen“, und bei einem unerwarteten Fehler erscheint eine ruhige Meldung statt eines eingefrorenen Bildschirms"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Speed check": "Geschwindigkeitstest", "Speed check and test products": "Geschwindigkeitstest und Testprodukte", "See how fast Pesa runs here, and load test products to try it": "Sehen Sie, wie schnell Pesa hier läuft, und laden Sie Testprodukte zum Ausprobieren", "See how fast Pesa searches, scans barcodes and draws the product list on this computer or device. Nothing is saved or sent anywhere.": "Sehen Sie, wie schnell Pesa auf diesem Computer oder Gerät sucht, Barcodes scannt und die Produktliste aufbaut. Nichts wird gespeichert oder irgendwohin gesendet.", "Test products": "Testprodukte", "Load a pile of made-up products to try Pesa yourself: scroll, search, scan a barcode, open the till. They are never saved or synced, they cannot be sold, and they disappear when you reload. Your stock totals and alerts include them while they are loaded.": "Laden Sie einen Stapel erfundener Produkte, um Pesa selbst auszuprobieren: scrollen, suchen, einen Barcode scannen, die Kasse öffnen. Sie werden nie gespeichert oder synchronisiert, können nicht verkauft werden und verschwinden beim Neuladen. Ihre Bestandssummen und Warnungen enthalten sie, solange sie geladen sind.", "How many": "Wie viele", "Load test products": "Testprodukte laden", "Remove test products": "Testprodukte entfernen", "Run the check": "Test ausführen", "Run speed check": "Geschwindigkeitstest starten", "test products are loaded.": "Testprodukte sind geladen.", "of your own products.": "Ihrer eigenen Produkte.", "test products loaded": "Testprodukte geladen", "Test products removed": "Testprodukte entfernt", "Test products on": "Testprodukte aktiv", "Tap to remove": "Zum Entfernen tippen", "Your own products": "Ihre eigenen Produkte", "Test products you loaded": "Von Ihnen geladene Testprodukte", "A big shop (30,000 products)": "Ein großer Laden (30.000 Produkte)", "No products yet. Load test products above to see how Pesa copes.": "Noch keine Produkte. Laden Sie oben Testprodukte, um zu sehen, wie Pesa damit zurechtkommt.", "Prepare barcode lookup (once)": "Barcode-Suche vorbereiten (einmalig)", "One barcode scan": "Ein Barcode-Scan", "One search": "Eine Suche", "Draw the first page": "Erste Seite aufbauen", "barcodes were not found": "Barcodes wurden nicht gefunden", "Times are for this computer or device right now. Fast means you will not notice a delay. Run it again with other apps closed if a result looks slow.": "Die Zeiten gelten für diesen Computer oder dieses Gerät jetzt gerade. Schnell bedeutet, dass Sie keine Verzögerung bemerken. Starten Sie den Test mit geschlossenen anderen Apps erneut, wenn ein Ergebnis langsam wirkt.", "Test products cannot be sold. Remove them from the cart first.": "Testprodukte können nicht verkauft werden. Entfernen Sie sie zuerst aus dem Warenkorb.", "A speed check shows how fast Pesa runs on your computer or device, and you can load test products to try a very big shop. Test products are never saved, synced or sold": "Ein Geschwindigkeitstest zeigt, wie schnell Pesa auf Ihrem Computer oder Gerät läuft, und Sie können Testprodukte laden, um einen sehr großen Laden auszuprobieren. Testprodukte werden nie gespeichert, synchronisiert oder verkauft"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Pesa is a point of sale and business management application built for small and medium shops. It helps an owner and their staff run the daily operations of a shop from a single app on a computer, tablet or other device, whether the shop has one location or several branches.": "Pesa ist eine Kassen- und Geschäftsverwaltungsanwendung für kleine und mittlere Läden. Sie hilft Inhabern und ihren Mitarbeitern, den Alltag eines Ladens mit einer einzigen App auf einem Computer, Tablet oder anderen Gerät zu führen, ob der Laden einen Standort oder mehrere Filialen hat.", "Beyond the till, Pesa includes business tools for profit, stock, credit, loyalty, quotes and imports, tax records, and a speed check so you can see how well it runs on your own computer or device.": "Neben der Kasse bietet Pesa Geschäftswerkzeuge für Gewinn, Bestand, Kredit, Treue, Angebote und Importe, Steuerbelege, die für NamRA bereit sind, und einen Geschwindigkeitstest, damit Sie sehen, wie gut es auf Ihrem eigenen Computer oder Gerät läuft.", "Support for English, Afrikaans and German, with more of the app translated over time": "Unterstützung für Englisch, Afrikaans und Deutsch, wobei im Lauf der Zeit mehr von der App übersetzt wird", "A staff training section with narrated lessons covering the main parts of the app": "Ein Schulungsbereich für Mitarbeiter mit gesprochenen Lektionen zu den wichtigsten Teilen der App", "Business tools for the owner and managers: end of day summary, profit and targets, staff performance, stock and expiry, who owes me, loyalty rewards, quotes and recurring invoices, barcode labels, importing customers and products, a second currency, and a setup guide": "Geschäftswerkzeuge für Inhaber und Manager: Tagesabschluss, Gewinn und Ziele, Mitarbeiterleistung, Bestand und Verfallsdaten, wer mir Geld schuldet, Treuebelohnungen, Angebote und wiederkehrende Rechnungen, Barcode Etiketten, Import von Kunden und Produkten, eine zweite Währung und eine Einrichtungshilfe", "An import cost calculator that shares freight, clearing fees and customs duty across imported products to show the true cost of each, and can save it as the cost price": "Ein Importkosten Rechner, der Fracht, Abfertigungsgebühren und Zoll auf importierte Produkte verteilt, die wahren Kosten jedes Produkts zeigt und sie als Einkaufspreis speichern kann", "A mobile money check that lines up payment messages you paste in with the wallet sales you recorded. Pesa cannot read your messages by itself": "Ein Mobile Money Abgleich, der eingefügte Zahlungsnachrichten mit den erfassten Wallet Verkäufen abgleicht. Pesa kann Ihre Nachrichten nicht selbst lesen", "A check at the till that warns about items with no price, items priced below cost, and alcohol or tobacco marked tax exempt. It only warns, it never blocks a sale": "Eine Prüfung an der Kasse, die vor Artikeln ohne Preis, Artikeln unter dem Einkaufspreis und als steuerfrei markiertem Alkohol oder Tabak warnt. Sie warnt nur und sperrt nie einen Verkauf", "Tax records: the owner can switch on a numbered, tamper evident record of every sale. It works offline and never slows a sale. Electronic invoicing requirements are to be confirmed with the relevant authorities of Namibia, so nothing is sent until connection details exist, and Pesa does not claim NamRA approval": "Steuerbelege bereit für NamRA: Der Inhaber kann einen nummerierten, manipulationssicheren Beleg für jeden Verkauf einschalten. Er funktioniert offline und bremst nie einen Verkauf. NamRA hat seine Regeln für elektronische Rechnungen noch nicht veröffentlicht, daher wird nichts gesendet, bis Verbindungsdaten vorliegen, und Pesa behauptet keine Zulassung durch NamRA", "Company details with the BIPA registration number, the legal name on the BIPA certificate and the NamRA VAT number. Pesa checks that the BIPA number looks right but cannot confirm it with BIPA, so it records that you entered it yourself": "Firmendaten mit der BIPA Registrierungsnummer, dem rechtlichen Namen auf dem BIPA Zertifikat und der NamRA MwSt Nummer. Pesa prüft, ob die BIPA Nummer plausibel aussieht, kann sie aber nicht mit BIPA bestätigen und vermerkt daher, dass Sie sie selbst eingegeben haben", "Download any document as PDF, Word, Excel, CSV, web page, rich text, plain text or a picture": "Laden Sie jedes Dokument als PDF, Word, Excel, CSV, Webseite, Rich Text, reinen Text oder Bild herunter", "Sign in protection: strong passwords, limits on guessing, automatic sign out, fingerprint or face approval before records are deleted or restored, and a Security check page for the owner": "Anmeldeschutz: starke Passwörter, Begrenzung von Rateversuchen, automatische Abmeldung, Fingerabdruck oder Gesichtsfreigabe vor dem Löschen oder Wiederherstellen von Daten und eine Sicherheitsprüfung für den Inhaber", "Backups on the device and, on browsers that allow it, in a folder you choose, for example one that syncs to cloud storage": "Sicherungen auf dem Gerät und, in Browsern die es erlauben, in einem Ordner Ihrer Wahl, zum Beispiel einem, der mit Cloud Speicher synchronisiert", "Text size and contrast settings, a setup guide, help search, and a check of how well this computer or device runs Pesa": "Einstellungen für Textgröße und Kontrast, eine Einrichtungshilfe, Hilfesuche und eine Prüfung, wie gut dieser Computer oder dieses Gerät Pesa ausführt", "A speed check and test products: see how fast Pesa searches, scans and draws the product list on this computer or device, and load made up test products to try a very big shop. Test products are never saved, synced, backed up or sold": "Ein Geschwindigkeitstest und Testprodukte: Sehen Sie, wie schnell Pesa auf diesem Computer oder Gerät sucht, scannt und die Produktliste aufbaut, und laden Sie erfundene Testprodukte, um einen sehr großen Laden auszuprobieren. Testprodukte werden nie gespeichert, synchronisiert, gesichert oder verkauft", "Terms, privacy and support pages that say plainly what Pesa does and does not do": "Seiten zu Bedingungen, Datenschutz und Support, die klar sagen, was Pesa tut und was nicht", "A welcome animation when Pesa opens, which you can skip or turn off": "Eine Begrüßungsanimation beim Öffnen von Pesa, die Sie überspringen oder ausschalten können", "Licence and subscription: when your Pesa provider switches it on, the owner enters a licence key and Pesa checks the plan on the device": "Lizenz und Abonnement: Wenn Ihr Pesa Anbieter es einschaltet, gibt der Inhaber einen Lizenzschlüssel ein und Pesa prüft den Tarif auf dem Gerät", "Business tools, the import cost calculator, the mobile money check, tax records and the speed check": "Geschäftswerkzeuge, der Importkosten Rechner, der Mobile Money Abgleich, Steuerbelege und der Geschwindigkeitstest", "Voice search on most computers and devices, because the device’s speech service works online": "Die Sprachsuche auf den meisten Computern und Geräten, weil der Sprachdienst des Geräts online arbeitet", "Sending tax records to an authority, once the requirements are confirmed and connection details have been entered. Until then the records stay on the device": "Senden von Steuerbelegen an NamRA, sobald Verbindungsdaten eingegeben sind. Bis dahin warten die Belege sicher auf dem Gerät", "Test products live in memory only. They are never saved, so they disappear when you reload": "Testprodukte existieren nur im Speicher. Sie werden nie gespeichert und verschwinden daher beim Neuladen", "It connects your computers, tablets and other devices to one business, so every device shows the same sales, stock, customers and credit": "Es verbindet Ihre Computer, Tablets und anderen Geräte mit einem Geschäft, sodass jedes Gerät dieselben Verkäufe, denselben Bestand, dieselben Kunden und denselben Kredit zeigt", "Two devices on the same WiFi connect directly to each other, encrypted, and swap their newest changes. A router with no internet works, and so does one device’s hotspot": "Zwei Geräte im selben WLAN verbinden sich direkt, verschlüsselt, und tauschen ihre neuesten Änderungen aus. Ein Router ohne Internet funktioniert, ebenso der Hotspot eines Geräts", "Alerts and checks run only while Pesa is open or was used recently. A browser cannot run a web app in the background the way a device’s own apps can": "Warnungen und Prüfungen laufen nur, solange Pesa geöffnet ist oder kürzlich benutzt wurde. Ein Browser kann eine Web App nicht im Hintergrund ausführen, wie es die eigenen Apps eines Geräts können", "End of day summary: takings, cash, top sellers, profit and a ready message to send": "Tagesabschluss: Einnahmen, Bargeld, Bestseller, Gewinn und eine fertige Nachricht zum Senden", "Profit and targets: profit for each product, busy times, and daily and monthly goals": "Gewinn und Ziele: Gewinn je Produkt, Stoßzeiten sowie Tages und Monatsziele", "Staff performance: sales for each person and bonus goals": "Mitarbeiterleistung: Verkäufe je Person und Bonusziele", "Stock and expiry: low stock, products close to their expiry date, and orders grouped by supplier": "Bestand und Verfall: niedriger Bestand, Produkte kurz vor dem Verfallsdatum und nach Lieferanten gruppierte Bestellungen", "Who owes me: customers listed by how long they have owed, with payment reminders": "Wer mir Geld schuldet: Kunden nach Dauer der Schuld, mit Zahlungserinnerungen", "Loyalty rewards: regular customers earn points that they can use on later sales": "Treuebelohnungen: Stammkunden sammeln Punkte, die sie bei späteren Verkäufen einlösen können", "Quotes and recurring invoices: send a quote and turn it into an invoice in one tap, and set up invoices for customers you bill again and again, with a reminder when each is due": "Angebote und wiederkehrende Rechnungen: Senden Sie ein Angebot und machen Sie daraus mit einem Tipp eine Rechnung, und richten Sie Rechnungen für Kunden ein, die Sie immer wieder abrechnen, mit einer Erinnerung bei Fälligkeit", "Barcode labels: print shelf and price labels": "Barcode Etiketten: Regal und Preisetiketten drucken", "Import customers and products from a spreadsheet saved as CSV": "Kunden und Produkte aus einer als CSV gespeicherten Tabelle importieren", "Currency and converter: show a second currency at the till and take cash in it. The Namibian dollar is tied one to one to the South African rand, and you type other rates yourself": "Währung und Umrechner: Zeigen Sie an der Kasse eine zweite Währung und nehmen Sie Bargeld darin an. Der Namibia Dollar ist eins zu eins an den südafrikanischen Rand gebunden, andere Kurse geben Sie selbst ein", "Setup guide: a short checklist that takes a new owner through the first steps": "Einrichtungshilfe: eine kurze Checkliste, die neue Inhaber durch die ersten Schritte führt", "Import cost calculator: enter the supplier prices plus freight, clearing fees and customs duty, and Pesa shares the extra costs across the products to show the true cost of each. You can save it as the product cost price. Import VAT is not included": "Importkosten Rechner: Geben Sie die Lieferantenpreise sowie Fracht, Abfertigungsgebühren und Zoll ein, und Pesa verteilt die Zusatzkosten auf die Produkte, um die wahren Kosten jedes Produkts zu zeigen. Sie können sie als Einkaufspreis speichern. Einfuhr MwSt ist nicht enthalten", "Mobile money check: copy payment messages from your messages app, paste them in, pick a day, and Pesa lines them up with the wallet sales you recorded. It lists sales with no message and messages with no sale. Pesa reads the amount and reference from the wording, so glance at anything marked as not matched": "Mobile Money Abgleich: Kopieren Sie Zahlungsnachrichten aus Ihrer Nachrichten App, fügen Sie sie ein, wählen Sie einen Tag, und Pesa gleicht sie mit den erfassten Wallet Verkäufen ab. Er listet Verkäufe ohne Nachricht und Nachrichten ohne Verkauf auf. Pesa liest Betrag und Referenz aus dem Wortlaut, prüfen Sie daher alles, was als nicht zugeordnet markiert ist", "Speed check and test products: run a check of searching, barcode scanning and drawing the product list, and load from 1,000 to 50,000 made up test products to try a very big shop. Test products are never saved, synced, backed up or sold, and tapping the notice removes them": "Geschwindigkeitstest und Testprodukte: Testen Sie Suche, Barcode Scan und den Aufbau der Produktliste und laden Sie 1.000 bis 50.000 erfundene Testprodukte, um einen sehr großen Laden auszuprobieren. Testprodukte werden nie gespeichert, synchronisiert, gesichert oder verkauft, und ein Tipp auf den Hinweis entfernt sie", "Business tools (Owner and Manager, from the menu)": "Geschäftswerkzeuge (Inhaber und Manager, im Menü)", "Barcodes are found instantly through an index, however many products you have": "Barcodes werden über einen Index sofort gefunden, egal wie viele Produkte Sie haben", "The point of sale product list loads in pages of 120 with a Show more button, and searching waits until you pause typing, so a very large shop does not freeze": "Die Produktliste der Kasse lädt in Seiten zu 120 mit einer Schaltfläche Mehr anzeigen, und die Suche wartet, bis Sie mit dem Tippen pausieren, sodass ein sehr großer Laden nicht einfriert", "If something unexpected goes wrong, Pesa shows one calm message instead of a frozen screen. Your saved records are not affected": "Wenn etwas Unerwartetes schiefgeht, zeigt Pesa eine ruhige Meldung statt eines eingefrorenen Bildschirms. Ihre gespeicherten Daten sind nicht betroffen", "Speeds depend on the computer or device. The Speed check shows the real figures for yours": "Die Geschwindigkeit hängt vom Computer oder Gerät ab. Der Geschwindigkeitstest zeigt die echten Werte für Ihres", "Speed and reliability": "Geschwindigkeit und Zuverlässigkeit", "Pesa cannot read text messages by itself, so the mobile money check only works on messages you paste in": "Pesa kann SMS nicht selbst lesen, daher funktioniert der Mobile Money Abgleich nur mit Nachrichten, die Sie einfügen", "A BIPA registration number is saved as entered by you. Pesa cannot confirm it with BIPA, so it never shows a number as verified": "Eine BIPA Registrierungsnummer wird so gespeichert, wie Sie sie eingegeben haben. Pesa kann sie nicht mit BIPA bestätigen und zeigt daher nie eine Nummer als bestätigt an", "Tax records are kept on the device. Requirements are to be confirmed with the relevant authorities of Namibia, and nothing is sent anywhere until connection details are entered": "Steuerbelege werden für NamRA bereitgehalten, aber Pesa behauptet nicht, von NamRA zugelassen zu sein, und es wird nichts gesendet, bis NamRA seine Regeln veröffentlicht und Sie Verbindungsdaten eingeben", "Pesa records and checks payments but does not move money, and it does not process cards": "Pesa erfasst und prüft Zahlungen, bewegt aber kein Geld und verarbeitet keine Karten", "The About page and its PDF now describe everything Pesa can do, including business tools, tax records, the import cost calculator, the mobile money check, the speed check and the limits of each": "Die Seite Über Pesa und ihr PDF beschreiben jetzt alles, was Pesa kann, einschließlich Geschäftswerkzeugen, Steuerbelegen, Importkosten Rechner, Mobile Money Abgleich, Geschwindigkeitstest und den Grenzen jedes Werkzeugs"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Meet the developer": "Lernen Sie den Entwickler kennen", "Hello and welcome to Pesa! My name is Björn Van Rensburg. I am a 30 year old software developer, born and raised right here in Windhoek, Namibia.": "Hallo und willkommen bei Pesa! Mein Name ist Björn Van Rensburg. Ich bin ein 30 Jahre alter Softwareentwickler, geboren und aufgewachsen hier in Windhoek, Namibia.", "Why I built Pesa": "Warum ich Pesa gebaut habe", "I built Pesa because I watched local Namibian shop owners struggle for years with expensive, over complicated point of sale systems imported from South Africa. Those corporate systems do not understand what it is like when our local internet towers go down, or how vital mobile wallets like PayToday, easyWallet and Blue Wallet are to our daily trade. Pesa was built specifically to solve those unique Namibian realities.": "Ich habe Pesa gebaut, weil ich jahrelang gesehen habe, wie einheimische namibische Ladenbesitzer mit teuren, überkomplizierten Kassensystemen aus Südafrika kämpfen. Diese Konzernsysteme verstehen nicht, wie es ist, wenn unsere lokalen Funkmasten ausfallen, oder wie wichtig mobile Wallets wie PayToday, easyWallet und Blue Wallet für unseren täglichen Handel sind. Pesa wurde speziell gebaut, um diese besonderen namibischen Gegebenheiten zu lösen.", "Your Mula, Your Pride": "Ihr Mula, Ihr Stolz", "Because the phrase Your Mula, Your Pride is our core promise, this application comes with a strict confidentiality agreement. Here are the three promises that matter most.": "Weil der Satz Ihr Mula, Ihr Stolz unser Kernversprechen ist, kommt diese Anwendung mit einer strengen Vertraulichkeitsvereinbarung. Hier sind die drei wichtigsten Versprechen.", "You can read the full agreement any time under Menu, Terms, privacy and support, and on the About Pesa page.": "Sie können die vollständige Vereinbarung jederzeit unter Menü, Bedingungen, Datenschutz und Support sowie auf der Seite Über Pesa lesen.", "Promise one: total data sovereignty": "Versprechen eins: volle Datenhoheit", "Your sales, inventory and customer credits belong strictly to your shop. I have zero access to your margins.": "Ihre Verkäufe, Ihr Bestand und Ihr Kundenkredit gehören ausschließlich Ihrem Laden. Ich habe keinerlei Zugriff auf Ihre Margen.", "Promise two: no central server trackers": "Versprechen zwei: keine zentralen Server Tracker", "Pesa saves your data to your own computer or device first. If you turn on cloud syncing, it connects only to a private online database that you control through Supabase.": "Pesa speichert Ihre Daten zuerst auf Ihrem eigenen Computer oder Gerät. Wenn Sie die Cloud Synchronisierung einschalten, verbindet es sich nur mit einer privaten Online Datenbank, die Sie über Supabase selbst steuern.", "Promise three: no hidden backdoors": "Versprechen drei: keine versteckten Hintertüren", "The application does not send usage tracking, background analytics or financial reports back to me.": "Die Anwendung sendet weder Nutzungsverfolgung noch Hintergrundanalysen noch Finanzberichte an mich zurück.", "To be fully open: the first time Pesa is opened online it fetches its fonts and its PDF tool from public servers, a password reset email is sent only if the owner sets that up, and tax records go to NamRA only if you enter its details. None of these carry your business records to me.": "Um ganz offen zu sein: Beim ersten Öffnen von Pesa online holt es seine Schriften und sein PDF Werkzeug von öffentlichen Servern, eine E Mail zum Zurücksetzen des Passworts wird nur gesendet, wenn der Inhaber sie einrichtet, und Steuerbelege gehen nur an NamRA, wenn Sie dessen Daten eingeben. Nichts davon überträgt Ihre Geschäftsdaten an mich.", "Thank you, and how to reach me": "Danke, und wie Sie mich erreichen", "Thank you for choosing local innovation to drive Namibia's retail growth. If you ever have technical feedback or questions during your store operations, you can reach me directly on WhatsApp at 081 821 1692, or by email at ecrypted5@gmail.com.": "Danke, dass Sie sich für lokale Innovation entscheiden, die Namibias Einzelhandel voranbringt. Wenn Sie jemals technisches Feedback oder Fragen im Ladenbetrieb haben, erreichen Sie mich direkt per WhatsApp unter 081 821 1692 oder per E Mail an ecrypted5@gmail.com.", "Meet the developer and your privacy promise": "Lernen Sie den Entwickler kennen und Ihr Datenschutzversprechen", "Menu → About Pesa": "Menü → Über Pesa", "Menu → Terms, privacy and support": "Menü → Bedingungen, Datenschutz und Support", "Menu → About Pesa → Your privacy and confidentiality": "Menü → Über Pesa → Ihre Privatsphäre und Vertraulichkeit", "Settings → Advanced Pesa Connection settings": "Einstellungen → Erweiterte Pesa Verbindungseinstellungen", "Menu → About Pesa → Contact the developer": "Menü → Über Pesa → Entwickler kontaktieren", "A new first training lesson, Meet the developer and your privacy promise, with a narrated message from the developer about why Pesa was built and what it never does with your records": "Eine neue erste Schulungslektion, Lernen Sie den Entwickler kennen und Ihr Datenschutzversprechen, mit einer gesprochenen Botschaft des Entwicklers dazu, warum Pesa gebaut wurde und was es nie mit Ihren Daten tut"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Pilot feedback form": "Pilot Feedbackformular", "A 48 hour pilot run. Please fill this in by hand while you work. Be honest: every problem you write down helps make Pesa better. Do not write passwords, PINs or customers’ personal details on this form.": "Ein 48 Stunden Pilotlauf. Bitte füllen Sie dies von Hand aus, während Sie arbeiten. Seien Sie ehrlich: Jedes Problem, das Sie notieren, hilft, Pesa zu verbessern. Schreiben Sie keine Passwörter, PINs oder persönlichen Kundendaten auf dieses Formular.", "About you and the pilot": "Zu Ihnen und zum Pilotlauf", "Cashier name": "Name des Kassierers", "Shop or branch": "Laden oder Filiale", "Device used (computer, tablet or other)": "Verwendetes Gerät (Computer, Tablet oder anderes)", "Shifts I worked": "Schichten, die ich gearbeitet habe", "Pilot started (date and time)": "Pilot gestartet (Datum und Uhrzeit)", "Pilot ended (date and time)": "Pilot beendet (Datum und Uhrzeit)", "How easy was it? Circle one number for each line": "Wie einfach war es? Kreisen Sie in jeder Zeile eine Zahl ein", "1 = very hard    3 = fine    5 = very easy": "1 = sehr schwer    3 = in Ordnung    5 = sehr leicht", "Making a sale at the till": "Einen Verkauf an der Kasse abwickeln", "Finding a product by name or barcode": "Ein Produkt nach Name oder Barcode finden", "Taking cash, card or wallet payments": "Bar , Karten oder Wallet Zahlungen annehmen", "Printing or sharing receipts": "Belege drucken oder teilen", "Opening and closing my till": "Meine Kasse öffnen und schließen", "Working when the internet was down": "Arbeiten, als das Internet ausgefallen war", "Speed of the app overall": "Geschwindigkeit der App insgesamt", "Overall, how easy was Pesa to use?": "Insgesamt: Wie einfach war Pesa zu benutzen?", "Numbers for my shift or shifts": "Zahlen für meine Schicht(en)", "About how many sales did I make?": "Ungefähr wie viele Verkäufe habe ich gemacht?", "Times Pesa was slow or froze": "Wie oft Pesa langsam war oder eingefroren ist", "Times the internet was down": "Wie oft das Internet ausgefallen war", "Times a barcode would not scan": "Wie oft ein Barcode sich nicht scannen ließ", "Times I needed help from someone": "Wie oft ich Hilfe von jemandem brauchte", "Sales I had to correct or cancel": "Verkäufe, die ich korrigieren oder stornieren musste", "Working without internet (tick one box for each question)": "Arbeiten ohne Internet (pro Frage ein Kästchen ankreuzen)", "Did Pesa keep working when the internet was down?": "Hat Pesa weitergearbeitet, als das Internet ausgefallen war?", "Did my sales show up on the other devices afterwards?": "Sind meine Verkäufe danach auf den anderen Geräten erschienen?", "Partly": "Teilweise", "It did not happen": "Es ist nicht vorgekommen", "Not tried": "Nicht versucht", "Not sure": "Nicht sicher", "Not yet": "Noch nicht", "Problem log: write down anything that went wrong": "Problemprotokoll: Notieren Sie alles, was schiefgegangen ist", "What I was doing": "Was ich gerade tat", "What went wrong": "Was schiefgegangen ist", "How bad?": "Wie schlimm?", "How bad: S = small, A = annoying, X = stopped the sale. Circle one letter.": "Wie schlimm: S = klein, A = lästig, X = Verkauf gestoppt. Kreisen Sie einen Buchstaben ein.", "In my own words": "In meinen eigenen Worten", "What worked best for me?": "Was hat für mich am besten funktioniert?", "What was most confusing or slow?": "Was war am verwirrendsten oder langsamsten?", "What did customers say or do?": "Was haben Kunden gesagt oder getan?", "What is the first thing I would change?": "Was würde ich als Erstes ändern?", "My verdict (tick one box for each question)": "Mein Urteil (pro Frage ein Kästchen ankreuzen)", "Would I use Pesa every day?": "Würde ich Pesa jeden Tag benutzen?", "Would I trust Pesa to run my till on its own?": "Würde ich Pesa zutrauen, meine Kasse allein zu führen?", "Signatures": "Unterschriften", "Cashier signature": "Unterschrift des Kassierers", "Reviewed by owner or manager": "Geprüft von Inhaber oder Manager", "Owner or manager notes": "Notizen von Inhaber oder Manager", "Print it and note how Pesa works for you during the 48 hour pilot.": "Drucken Sie es aus und notieren Sie, wie Pesa im 48 Stunden Pilotlauf für Sie funktioniert.", "Print this form and fill it in by hand while you work during the 48 hour pilot run. Hand it to the owner when the pilot ends.": "Drucken Sie dieses Formular aus und füllen Sie es während des 48 Stunden Pilotlaufs von Hand aus. Geben Sie es dem Inhaber, wenn der Pilot endet.", "What is on the form": "Was auf dem Formular steht", "Name, shop, device and when the pilot started": "Name, Laden, Gerät und Beginn des Piloten", "How easy was it?": "Wie einfach war es?", "Eight lines to rate from 1 to 5": "Acht Zeilen zum Bewerten von 1 bis 5", "Sales made, slow moments, internet down, scans that failed": "Getätigte Verkäufe, langsame Momente, Internet aus, fehlgeschlagene Scans", "Working without internet": "Arbeiten ohne Internet", "Did it keep working, and did the sales show up later": "Hat es weitergearbeitet, und sind die Verkäufe später erschienen", "Problem log": "Problemprotokoll", "Eight lines for date, what happened and how bad": "Acht Zeilen für Datum, Vorfall und Schweregrad", "What worked, what confused, what customers said, what to change": "Was funktionierte, was verwirrte, was Kunden sagten, was zu ändern ist", "My verdict": "Mein Urteil", "Would I use it every day, and trust it on its own": "Würde ich es täglich nutzen und ihm allein vertrauen", "Cashier and owner or manager": "Kassierer und Inhaber oder Manager", "Fill in my name and the shop": "Meinen Namen und den Laden eintragen", "Pilot starts": "Pilot beginnt", "If you enter it, the form also prints when the 48 hours end.": "Wenn Sie es eingeben, druckt das Formular auch, wann die 48 Stunden enden.", "Download or print the form": "Formular herunterladen oder drucken", "Open the downloaded file and print it. Choose Word if you want to change the wording first.": "Öffnen Sie die heruntergeladene Datei und drucken Sie sie. Wählen Sie Word, wenn Sie zuerst den Wortlaut ändern möchten.", "Show the Pilot feedback form card on employee dashboards": "Die Karte Pilot Feedbackformular auf den Mitarbeiter Dashboards anzeigen", "Form downloaded": "Formular heruntergeladen", "Couldn’t make the form. Please try again.": "Das Formular konnte nicht erstellt werden. Bitte versuchen Sie es erneut.", "Hand this form to the shop owner when the pilot ends. If a problem needs the developer, contact him on WhatsApp 081 821 1692 or by email at ecrypted5@gmail.com.": "Geben Sie dieses Formular dem Ladeninhaber, wenn der Pilot endet. Wenn ein Problem den Entwickler braucht, erreichen Sie ihn per WhatsApp unter 081 821 1692 oder per E Mail an ecrypted5@gmail.com.", "A printable pilot feedback form for cashiers, on the employee dashboard and in the menu, with ratings, a problem log and space for their own words": "Ein druckbares Pilot Feedbackformular für Kassierer, im Mitarbeiter Dashboard und im Menü, mit Bewertungen, einem Problemprotokoll und Platz für eigene Worte", "A printable Pilot feedback form for cashiers to log how Pesa works for them during the 48 hour pilot run. Find it on the employee dashboard and in the menu": "Ein druckbares Pilot Feedbackformular, in dem Kassierer festhalten, wie Pesa im 48 Stunden Pilotlauf für sie funktioniert. Zu finden im Mitarbeiter Dashboard und im Menü"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Invoice": "Rechnung", "Tax invoice": "Steuerrechnung", "VAT registration no.": "USt-Registrierungsnr.", "Net total excl. VAT": "Nettosumme ohne MwSt.", "VAT {0}": "MwSt. {0}", "Gross total due": "Brutto fällig", "Document verification signature": "Dokumentprüfsignatur", "Reserved for a verification code. Requirements are to be confirmed with the relevant authorities of Namibia.": "Reserviert für einen kryptografischen Prüfcode. Solange im Feld unten kein Code gedruckt ist, wurde dieses Dokument nicht von NamRA validiert.", "Verification code": "Prüfcode", "Customer TIN (optional, for business customers)": "TIN des Kunden (optional, für Geschäftskunden)", "Your TIN is not set, so it will not print on this tax invoice. Add it in Settings, Tax records.": "Ihre TIN ist nicht hinterlegt und wird daher nicht auf dieser Steuerrechnung gedruckt. Tragen Sie sie unter Einstellungen, Steuerdaten ein.", "Dairy products": "Milchprodukte", "Bakery": "Backwaren", "Cold drinks and water": "Kaltgetränke und Wasser", "Meat and fish": "Fleisch und Fisch", "Fruit and vegetables": "Obst und Gemüse", "Dry goods and groceries": "Trockenwaren und Lebensmittel", "Household and cleaning": "Haushalt und Reinigung", "Toiletries and health": "Körperpflege und Gesundheit", "Snacks and sweets": "Snacks und Süßigkeiten", "Other products": "Sonstige Produkte", "Tax invoices show your TIN and VAT registration number, the buyer's TIN, and a net, VAT, zero rated, exempt and gross breakdown. Stock is listed under department headers, and you can tick several products at a time on invoices, quotes and purchase orders": "Steuerrechnungen zeigen Ihre TIN und USt Registrierungsnummer, die TIN des Käufers sowie eine Aufschlüsselung in Netto, MwSt., nullbesteuert, befreit und Brutto. Der Bestand ist unter Abteilungsüberschriften gelistet, und Sie können auf Rechnungen, Angeboten und Bestellungen mehrere Produkte auf einmal ankreuzen"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Answers tapped in on screen in Pesa.": "Antworten am Bildschirm in Pesa angetippt.", "Small": "Klein", "Annoying": "Lästig", "Stopped the sale": "Verkauf gestoppt", "Computer": "Computer", "Tablet": "Tablet", "Other device": "Anderes Gerät", "No problems logged": "Keine Probleme erfasst", "Submitted in Pesa on": "In Pesa eingereicht am", "Your name": "Ihr Name", "e.g. Monday morning, Tuesday full day": "z. B. Montagvormittag, Dienstag ganztags", "Tap your answers. They save on this device as you go, so you can stop and come back. Do not write passwords, PINs or customers’ personal details.": "Tippen Sie Ihre Antworten an. Sie werden unterwegs auf diesem Gerät gespeichert, Sie können also unterbrechen und später weitermachen. Schreiben Sie keine Passwörter, PINs oder persönlichen Kundendaten.", "Add a problem": "Problem hinzufügen", "Add this problem": "Dieses Problem hinzufügen", "Remove": "Entfernen", "Write what went wrong first": "Schreiben Sie zuerst, was schiefgegangen ist", "Save and submit": "Speichern und einreichen", "Save and finish later": "Speichern und später fertigstellen", "Draft saved": "Entwurf gespeichert", "Answer at least one question first": "Beantworten Sie zuerst mindestens eine Frage", "Pilot feedback saved": "Pilot Feedback gespeichert", "Your form is saved on this device. Pesa cannot send it by itself, so tap a button to send a copy to the developer. Nothing leaves this device until you tap.": "Ihr Formular ist auf diesem Gerät gespeichert. Pesa kann es nicht selbst senden. Tippen Sie auf eine Schaltfläche, um dem Entwickler eine Kopie zu schicken. Nichts verlässt dieses Gerät, bevor Sie tippen.", "WhatsApp the developer": "Dem Entwickler per WhatsApp schreiben", "Email the developer": "Dem Entwickler eine E Mail senden", "Share or copy the answers": "Antworten teilen oder kopieren", "Download a PDF copy": "PDF Kopie herunterladen", "WhatsApp opened": "WhatsApp geöffnet", "Email opened": "E Mail geöffnet", "Shared or copied": "Geteilt oder kopiert", "PDF copy saved": "PDF Kopie gespeichert", "Copied": "Kopiert", "Couldn’t copy. Use the WhatsApp or email button instead.": "Kopieren war nicht möglich. Nutzen Sie stattdessen die WhatsApp oder E Mail Schaltfläche.", "Pilot feedback submitted. Thank you!": "Pilot Feedback eingereicht. Danke!", "Tap to send a copy to the developer again, or to fill in a new form.": "Tippen Sie, um dem Entwickler erneut eine Kopie zu senden oder ein neues Formular auszufüllen.", "You have a saved draft. Tap to finish it.": "Sie haben einen gespeicherten Entwurf. Tippen Sie, um ihn fertigzustellen.", "Tap here to answer it on screen. It takes about 5 minutes.": "Tippen Sie hier, um es am Bildschirm zu beantworten. Es dauert etwa 5 Minuten.", "Please fill in the pilot feedback form": "Bitte füllen Sie das Pilot Feedbackformular aus", "The 48 hours are over. Please send your form today.": "Die 48 Stunden sind vorbei. Bitte senden Sie Ihr Formular heute.", "The pilot ends in": "Der Pilot endet in", "hour": "Stunde", "hours": "Stunden", "Fill in the form here on screen by tapping your answers. When you submit, you can send a copy to the developer with one tap.": "Füllen Sie das Formular hier am Bildschirm aus, indem Sie Ihre Antworten antippen. Nach dem Einreichen können Sie mit einem Tipp eine Kopie an den Entwickler senden.", "Continue my form": "Mein Formular fortsetzen", "Fill in a new form": "Neues Formular ausfüllen", "Fill in the form on screen": "Formular am Bildschirm ausfüllen", "Forms I filled in on this device": "Formulare, die ich auf diesem Gerät ausgefüllt habe", "Send options used": "Sendeoptionen genutzt", "Not sent yet. Tap to send.": "Noch nicht gesendet. Zum Senden tippen.", "Paper copy": "Papierkopie", "Download or print a blank paper form": "Leeres Papierformular herunterladen oder drucken", "For the owner or manager": "Für Inhaber oder Manager", "The 48 hour pilot started": "Der 48 Stunden Pilot begann", "No pilot start time is set. Start it so everyone sees how long is left.": "Es ist keine Startzeit für den Pilot festgelegt. Starten Sie ihn, damit alle sehen, wie lange noch Zeit ist.", "Start the 48 hours now": "Die 48 Stunden jetzt starten", "Clear the start time": "Startzeit löschen", "Show the pilot reminder and form card to everyone": "Pilot Erinnerung und Formularkarte für alle anzeigen", "Reminder: please fill in the pilot feedback form.": "Erinnerung: Bitte füllen Sie das Pilot Feedbackformular aus.", "Fill in": "Ausfüllen", "Pilot feedback reminder": "Erinnerung Pilot Feedback", "Please take a few minutes to fill in the pilot feedback form. It helps make Pesa better for your shop.": "Bitte nehmen Sie sich ein paar Minuten, um das Pilot Feedbackformular auszufüllen. Das hilft, Pesa für Ihren Laden zu verbessern.", "Fill in now": "Jetzt ausfüllen", "Remind me later": "Später erinnern", "The pilot feedback form can be filled in on screen by tapping answers. A copy can be sent to the developer with one tap, and Pesa reminds everyone until it is done": "Das Pilot Feedbackformular lässt sich am Bildschirm durch Antippen ausfüllen. Mit einem Tipp kann eine Kopie an den Entwickler gesendet werden, und Pesa erinnert alle, bis es erledigt ist"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Accountant": "Buchhalter", "Accountant is for owners and managers": "Der Buchhalter ist für Inhaber und Manager", "Run report now": "Bericht jetzt erstellen", "File missing months": "Fehlende Monate ablegen", "Opening balances": "Eröffnungssalden", "Books start": "Buchführung beginnt", "First record in Pesa": "Erster Eintrag in Pesa", "Latest month filed": "Letzter abgelegter Monat", "None yet": "Noch keiner", "Checks": "Prüfungen", "Monthly accounting packs": "Monatliche Buchhaltungspakete", "VAT return working figures": "Arbeitszahlen für die MwSt Erklärung", "Filed": "Abgelegt", "Verified": "Geprüft", "Records changed since filing": "Daten seit Ablage geändert", "Hash does not match": "Hash stimmt nicht überein", "Journal": "Journal", "Trial balance": "Saldenliste", "Re-run month": "Monat neu erstellen", "Prepared": "Erstellt", "Prepared by": "Erstellt von", "Record hash": "Datensatz Hash", "This pack": "Dieses Paket", "Previous month": "Vormonat", "Earlier revisions": "Frühere Fassungen", "automatic": "automatisch", "Accounting pack": "Buchhaltungspaket", "Monthly accounting pack": "Monatliches Buchhaltungspaket", "Accounting pack downloaded": "Buchhaltungspaket heruntergeladen", "VAT working figures": "MwSt Arbeitszahlen", "VAT working figures downloaded": "MwSt Arbeitszahlen heruntergeladen", "Your VAT category": "Ihre MwSt Kategorie", "Return due by": "Erklärung fällig bis", "Period not finished": "Zeitraum noch nicht beendet", "Income statement": "Gewinn und Verlustrechnung", "Statement of financial position": "Bilanz", "Ledger summary by day": "Hauptbuch Zusammenfassung pro Tag", "Basis of preparation": "Grundlage der Erstellung", "Checks on these figures": "Prüfungen dieser Zahlen", "Passed": "Bestanden", "FAILED": "FEHLGESCHLAGEN", "Review": "Prüfen", "Sales (excluding VAT)": "Umsatz (ohne MwSt)", "Cost of goods sold and wastage": "Wareneinsatz und Schwund", "Total sales (excluding VAT)": "Gesamtumsatz (ohne MwSt)", "Stock wastage and shrinkage": "Bestandsschwund", "Total operating expenses": "Gesamte Betriebsausgaben", "Net profit for the period": "Reingewinn für den Zeitraum", "Net loss for the period": "Nettoverlust für den Zeitraum", "Output VAT (charged on sales)": "Umsatzsteuer (auf Verkäufe berechnet)", "Input VAT (on supplier tax invoices recorded)": "Vorsteuer (aus erfassten Lieferantenrechnungen)", "Net VAT payable to NamRA": "MwSt Zahllast an NamRA", "Net VAT refundable from NamRA": "MwSt Erstattung von NamRA", "Standard rated supplies, excluding VAT": "Normal besteuerte Leistungen, ohne MwSt", "Standard rated supplies, including VAT": "Normal besteuerte Leistungen, mit MwSt", "Zero rated supplies": "Nullsatz Leistungen", "Exempt supplies": "Befreite Leistungen", "Total supplies, including VAT": "Gesamtleistungen, mit MwSt", "Total assets": "Summe Aktiva", "Total liabilities": "Summe Verbindlichkeiten", "Total equity": "Summe Eigenkapital", "Total liabilities and equity": "Summe Verbindlichkeiten und Eigenkapital", "Prepared by Pesa from the sales, expenses, supplier invoices and payments, wastage and customer payments recorded in it, on an accrual basis, in Namibia Dollars (N$) to the cent. Cost of goods sold uses the cost price held on each product when it was sold. Stock, receivables and payables are the movements recorded in Pesa plus the opening balances entered.": "Von Pesa erstellt aus den darin erfassten Verkäufen, Ausgaben, Lieferantenrechnungen und Zahlungen, Schwund und Kundenzahlungen, nach dem Periodenprinzip, in Namibia Dollar (N$) auf den Cent genau. Der Wareneinsatz verwendet den beim Verkauf hinterlegten Einkaufspreis des Produkts. Bestand, Forderungen und Verbindlichkeiten sind die in Pesa erfassten Bewegungen plus die eingegebenen Eröffnungssalden.", "Pesa does not see your bank, fixed assets, loans, payroll taxes, owner drawings, income tax or imports, so those are not in these figures. A registered accountant should review them before they are used for annual financial statements, tax returns or a loan application.": "Pesa sieht Ihre Bank, Anlagevermögen, Darlehen, Lohnsteuern, Privatentnahmen, Einkommensteuer oder Importe nicht, daher sind sie in diesen Zahlen nicht enthalten. Ein zugelassener Buchhalter sollte sie prüfen, bevor sie für Jahresabschlüsse, Steuererklärungen oder einen Kreditantrag verwendet werden.", "These documents are prepared by software. They are not audited or reviewed, and they are to be confirmed with the relevant legal bodies, authorities and entities of Namibia and your accountant. Namibian tax law requires business records and supporting documents to be kept for at least five years, so keep this pack with your sales records, supplier tax invoices and bank statements.": "Diese Dokumente werden von Software erstellt. Sie sind weder geprüft noch durchgesehen und werden weder von NamRA noch von einem Buchhalter genehmigt oder beglaubigt. Das namibische Steuerrecht verlangt, Geschäftsunterlagen und Belege mindestens fünf Jahre aufzubewahren. Bewahren Sie dieses Paket daher zusammen mit Ihren Verkaufsunterlagen, Lieferantenrechnungen und Kontoauszügen auf.", "Not VAT registered": "Nicht MwSt registriert", "Choose": "Wählen", "Opening": "Anfang", "Debits": "Soll", "Credits": "Haben", "Closing": "Ende", "Lines": "Zeilen", "Result": "Ergebnis", "VAT on the supplier tax invoice (N$, optional)": "MwSt auf der Lieferantenrechnung (N$, optional)", "VAT on this tax invoice (N$, optional)": "MwSt auf dieser Rechnung (N$, optional)", "Only enter VAT you hold a valid tax invoice for. It is counted as input VAT in the Accountant.": "Geben Sie nur MwSt ein, für die Sie eine gültige Steuerrechnung haben. Sie wird im Buchhalter als Vorsteuer gezählt.", "monthly accounting pack filed in Accountant": "monatliches Buchhaltungspaket im Buchhalter abgelegt", "monthly accounting packs filed in Accountant": "monatliche Buchhaltungspakete im Buchhalter abgelegt", "Monthly accounting packs, VAT working figures, trial balance": "Monatliche Buchhaltungspakete, MwSt Arbeitszahlen, Saldenliste", "Books start on": "Buchführung beginnt am", "Cash on hand": "Bargeld", "Digital wallets": "Digitale Geldbörsen", "Bank balance": "Kontostand", "Stock at cost": "Bestand zu Kosten", "Owed to suppliers": "Schulden bei Lieferanten", "New revision filed": "Neue Fassung abgelegt", "Opening balances saved": "Eröffnungssalden gespeichert", "Opening balances cleared": "Eröffnungssalden gelöscht", "This month so far": "Dieser Monat bisher", "Last month": "Letzter Monat", "Run for these dates": "Für diese Daten erstellen", "Journal for these dates": "Journal für diese Daten", "No months filed yet": "Noch keine Monate abgelegt", "Preparing documents…": "Dokumente werden erstellt…", "Accountant: double entry books built to the cent from your sales, expenses, supplier invoices and payments, wastage and customer payments. Each finished month is filed automatically the first time the owner or a manager opens Pesa after month end, with a trial balance, income statement, VAT working figures and a hash that shows if a filed month was changed. Documents can also be run on demand. Pesa does not see your bank, and the documents are not approved by NamRA or an accountant": "Buchhalter: doppelte Buchführung, auf den Cent genau aus Ihren Verkäufen, Ausgaben, Lieferantenrechnungen und Zahlungen, Schwund und Kundenzahlungen erstellt. Jeder abgeschlossene Monat wird automatisch abgelegt, sobald der Inhaber oder ein Manager Pesa nach Monatsende zum ersten Mal öffnet, mit Saldenliste, Gewinn und Verlustrechnung, MwSt Arbeitszahlen und einem Hash, der zeigt, ob ein abgelegter Monat geändert wurde. Dokumente können auch auf Anfrage erstellt werden. Pesa sieht Ihre Bank nicht, und die Dokumente sind weder von NamRA noch von einem Buchhalter genehmigt"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Photo": "Foto", "Voice message": "Sprachnachricht", "Voice note": "Sprachnotiz", "Camera": "Kamera", "Attach": "Anhängen", "Call": "Anrufen", "Call on this device": "Auf diesem Gerät anrufen", "Open WhatsApp chat": "WhatsApp-Chat öffnen", "Pesa opens the dialer on this device. The call is made by your phone network, not inside Pesa.": "Pesa öffnet die Wähltastatur auf diesem Gerät. Der Anruf wird über Ihr Telefonnetz geführt, nicht in Pesa.", "No phone number saved for": "Keine Telefonnummer gespeichert für", "this person": "diese Person", "Add it in the profile first.": "Tragen Sie sie zuerst im Profil ein.", "Play voice message": "Sprachnachricht abspielen", "Could not play this voice note.": "Diese Sprachnotiz konnte nicht abgespielt werden.", "Save photo": "Foto speichern", "Recording": "Aufnahme", "Stop the recording first": "Beenden Sie zuerst die Aufnahme", "Choose a photo.": "Wählen Sie ein Foto.", "Could not read that photo.": "Das Foto konnte nicht gelesen werden.", "That voice note is too long to send. Keep it under 2 minutes.": "Diese Sprachnotiz ist zu lang zum Senden. Halten Sie sie unter 2 Minuten.", "Add a caption": "Beschriftung hinzufügen", "Read": "Gelesen", "Messages work like a chat, on a Pesa wallpaper. Send photos, record voice notes of up to two minutes, add emojis, and see ticks that turn gold when a message is read. The call button opens the dialer on this computer or device, or a WhatsApp chat. Pesa does not place calls itself. Messages are saved on the device first, so you can write and send while offline and they go out when the connection returns, as long as Advanced Pesa Connection is on. Photos are shrunk and voice notes are limited so they can be stored and synced with your shop data": "Nachrichten funktionieren wie ein Chat, auf einem Pesa Hintergrund. Senden Sie Fotos, nehmen Sie Sprachnotizen von bis zu zwei Minuten auf, fügen Sie Emojis hinzu und sehen Sie Häkchen, die golden werden, wenn eine Nachricht gelesen wurde. Die Anruftaste öffnet die Wähltastatur auf diesem Computer oder Gerät oder einen WhatsApp Chat. Pesa führt selbst keine Anrufe. Nachrichten werden zuerst auf dem Gerät gespeichert, sodass Sie offline schreiben und senden können und sie abgehen, sobald die Verbindung zurück ist, solange Erweiterte Pesa Verbindung eingeschaltet ist. Fotos werden verkleinert und Sprachnotizen begrenzt, damit sie mit Ihren Shopdaten gespeichert und synchronisiert werden können"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Waiting to send": "Wartet auf Versand", "You are offline. Messages are saved on this device and will send when you are back online.": "Sie sind offline. Nachrichten werden auf diesem Gerät gespeichert und gesendet, sobald Sie wieder online sind.", "Advanced Pesa Connection is off, so messages stay on this device. Turn it on in Settings so other devices receive them.": "Die erweiterte Pesa Verbindung ist aus, daher bleiben Nachrichten auf diesem Gerät. Schalten Sie sie in den Einstellungen ein, damit andere Geräte sie erhalten."}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Narrator voice": "Sprecherstimme", "Default": "Standard", "Male": "Männlich", "On this device": "Auf diesem Gerät", "Hear": "Anhören", "Male American English voices": "Männliche amerikanisch englische Stimmen", "No male American English voice is installed on this computer or device. Add one in the device settings under speech or text to speech voices, then reopen this page.": "Auf diesem Computer oder Gerät ist keine männliche amerikanisch englische Stimme installiert. Fügen Sie in den Geräteeinstellungen unter Sprache oder Text zu Sprache eine hinzu und öffnen Sie diese Seite dann erneut.", "Other English male voices": "Andere männliche englische Stimmen", "Deeper tone, where the device allows it": "Tieferer Ton, sofern das Gerät es erlaubt", "The voices come from your computer or device, so the list can differ from one device to the next. Recordings you made under My voice still play instead of these voices.": "Die Stimmen stammen von Ihrem Computer oder Gerät, die Liste kann also von Gerät zu Gerät abweichen. Aufnahmen unter Meine Stimme werden weiterhin anstelle dieser Stimmen abgespielt.", "Training lessons are read aloud, and you can choose a male American English voice from the voices installed on your computer or device, hear a sample first, and make the tone deeper where the device allows it. Pesa does not add new voices itself, so the choice depends on what your device has": "Die Schulungslektionen werden vorgelesen, und Sie können eine männliche amerikanisch englische Stimme aus den auf Ihrem Computer oder Gerät installierten Stimmen wählen, vorher eine Hörprobe anhören und den Ton tiefer machen, sofern das Gerät es erlaubt. Pesa fügt selbst keine neuen Stimmen hinzu, die Auswahl hängt also davon ab, was Ihr Gerät hat"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Pack": "Paket", "Journal downloaded": "Journal heruntergeladen", "Trial balance downloaded": "Saldenliste heruntergeladen", "This document is too long for a picture. Choose PDF, Excel or another format.": "Dieses Dokument ist zu lang für ein Bild. Wählen Sie PDF, Excel oder ein anderes Format.", "Accounting journal": "Buchhaltungsjournal", "Journal / line": "Journal / Zeile", "Entries": "Buchungen", "Interim, not filed": "Zwischenstand, nicht abgelegt", "Matches the filed copy": "Stimmt mit der abgelegten Kopie überein", "Records changed since the pack was filed": "Daten haben sich seit dem Ablegen des Pakets geändert", "Amounts are in NAD. Each line is one side of a journal: debits equal credits in every journal.": "Beträge in NAD. Jede Zeile ist eine Seite eines Journals: Soll gleich Haben in jedem Journal.", "Every Accountant document, including the journal and the trial balance, downloads as PDF, Word, Excel, CSV, web page, rich text, plain text or a picture. The Excel and CSV files keep every column, so your accountant can sort and check them": "Jedes Dokument des Buchhalters, einschließlich Journal und Saldenliste, wird als PDF, Word, Excel, CSV, Webseite, Rich Text, reiner Text oder Bild heruntergeladen. Die Excel und CSV Dateien behalten jede Spalte, damit Ihr Buchhalter sie sortieren und prüfen kann"}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"What the word Pesa means": "Was das Wort Pesa bedeutet", "Pesa is a Swahili word for money, used across East Africa and beyond. I chose it because money is what every shop lives on: what comes in, what goes out, and what is left at the end of the day. The whole app is built around that. Every sale, expense, credit account and cash up is a story about money, and Pesa keeps those stories clear and in order. It also sits beside our promise, Your Mula, Your Pride: it is your money, and the pride is in running your own shop well.": "Pesa ist ein Suaheli Wort für Geld und wird in ganz Ostafrika und darüber hinaus verwendet. Ich habe es gewählt, weil jedes Geschäft von Geld lebt: was hereinkommt, was hinausgeht und was am Ende des Tages übrig bleibt. Die ganze App ist darauf aufgebaut. Jeder Verkauf, jede Ausgabe, jedes Kreditkonto und jeder Kassenabschluss erzählt etwas über Geld, und Pesa hält diese Geschichten klar und geordnet. Es steht auch neben unserem Versprechen, Your Mula, Your Pride: Es ist Ihr Geld, und der Stolz liegt darin, Ihr eigenes Geschäft gut zu führen.", "Mula is the street word for money in Namibia, so the name and the promise say the same thing in two voices.": "Mula ist das Straßenwort für Geld in Namibia, der Name und das Versprechen sagen also dasselbe in zwei Stimmen."}); });
__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Keyboard shortcuts at the till: press / or F2 to jump to product search, and F9 or Ctrl and Enter to open the cart and charge. Buttons give a small press response when tapped, unless the simpler look or reduced motion is on":"Tastaturkürzel an der Kasse: Drücken Sie / oder F2, um zur Produktsuche zu springen, und F9 oder Strg und Eingabe, um den Warenkorb zu öffnen und zu kassieren. Schaltflächen reagieren beim Antippen mit einer kleinen Bewegung, außer wenn der einfachere Look oder reduzierte Bewegung aktiv ist","Seeing the Inter font from the web on a device that has never loaded it online. The PDF engine and the Pesa fonts come with the app, so PDFs and documents work offline":"Die Inter Schrift aus dem Web sehen, auf einem Gerät, das sie noch nie online geladen hat. Die PDF Engine und die Pesa Schriften sind in der App enthalten, daher funktionieren PDFs und Dokumente ohne Internet","The Accountant page shows profit or loss for any dates in a clear layout and makes a Profit and Loss report to keep, with a report number and fingerprints. Pesa lists the reports you make so you can check one later, can check all kept months and the chain between them, and can save a copy of the records and check that copy. Reports are prepared by software, are not audited, and are to be confirmed with your accountant":"Die Buchhalter Seite zeigt Gewinn oder Verlust für beliebige Daten in einem klaren Layout und erstellt einen Gewinn und Verlust Bericht zum Aufbewahren, mit Berichtsnummer und Fingerabdrücken. Pesa führt eine Liste der erstellten Berichte, damit Sie einen später prüfen können, kann alle archivierten Monate und die Kette zwischen ihnen prüfen und eine Kopie der Aufzeichnungen speichern und diese Kopie prüfen. Berichte werden von Software erstellt, sind nicht geprüft und sind mit Ihrem Buchhalter zu bestätigen","Profit or loss":"Gewinn oder Verlust","Make a report to keep":"Bericht zum Aufbewahren erstellen","More documents":"Weitere Dokumente","Reports you made":"Von Ihnen erstellte Berichte","Keep your records safe":"Sichern Sie Ihre Aufzeichnungen","Save the report":"Bericht speichern","Print the report":"Bericht drucken","Check a report":"Bericht prüfen","Check":"Prüfen","Check all records now":"Alle Aufzeichnungen jetzt prüfen","Save a copy of all records":"Kopie aller Aufzeichnungen speichern","Check a saved copy":"Gespeicherte Kopie prüfen","This month":"Dieser Monat","Last month":"Letzter Monat","This quarter":"Dieses Quartal","This year":"Dieses Jahr","Pick dates":"Daten wählen","Profit":"Gewinn","Loss":"Verlust","Break even":"Weder Gewinn noch Verlust","Money coming in":"Einnahmen","Money going out":"Ausgaben","Gross profit":"Bruttogewinn","Running costs":"Laufende Kosten","Total running costs":"Laufende Kosten gesamt","Profit and Loss report":"Gewinn und Verlust Bericht","Report no":"Berichtsnummer"}); });

__LL.de.push(function(LANGS){ Object.assign(LANGS.de.strings, {"Smart tools":"Clevere Werkzeuge","Stock and suppliers":"Lager und Lieferanten","Money and tax":"Geld und Steuern","Team and branches":"Team und Filialen","Pesa account and ads":"Pesa Konto und Werbung","Manage your business":"Geschäft verwalten"}); });
